import pty, os, subprocess, re, struct, fcntl, termios, sys
def run_pty(args, cols):
    # use script? create pty pair
    import os, pty
    master, slave = pty.openpty()
    # set winsize
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH", 24, cols, 0,0))
    p=subprocess.Popen(args, stdout=slave, stderr=slave, stdin=subprocess.DEVNULL, close_fds=True)
    os.close(slave)
    out=b""
    while True:
        try:
            d=os.read(master, 65536)
            if not d: break
            out+=d
        except OSError:
            break
    p.wait()
    os.close(master)
    return p.returncode, out.decode(errors='replace')

ansi=re.compile(r'\x1b\[[0-9;]*m|\x1b7|\x1b8|\x1b\[2K')
for cols in [50,80,100,120,200]:
    rc,out=run_pty(["./executable","--help"],cols)
    lines=[ansi.sub('',l) for l in out.splitlines()]
    print("COLS",cols,"max",max(len(l) for l in lines))
    if cols==200:
        for l in lines: print(repr(l))
PY
"}

