import datetime, subprocess, re
def make(series):
    lines=[]
    base=datetime.date(2021,1,1)
    days=len(next(iter(series.values())))
    for idx in range(days):
        d=base+datetime.timedelta(days=idx); ds=d.strftime("%d/%b/%Y")
        for pv,counts in series.items():
            for i in range(counts[idx]):
                lines.append(f'10.0.0.1 - - [{ds}:06:00:00 +0000] "GET {pv} HTTP/1.1" 200 100 "-" "UA"')
    open("/tmp/t/tmp.log","w").write("\n".join(lines)+"\n")
def trend(series):
    make(series)
    r=subprocess.run(["./executable","--color","no","--silent-load","-f","path","/tmp/t/tmp.log"],capture_output=True,text=True)
    rows={}
    for l in r.stdout.splitlines():
        m=re.search(r'│\s*\d+│(/\w+)\s*│.*?│(.*?)│\s*$',l)
        # simpler split by │
        parts=l.split('│')
        if len(parts)>=7 and parts[2].strip() in ('/a','/b'):
            rows[parts[2].strip()]=parts[6].strip()
    return rows

for x,y in [(1,5),(5,1),(1,10),(10,1),(10,20),(20,10),(5,10),(10,5),(1,2),(2,1),(1,100),(100,1),(10,11),(11,10)]:
    print(f"a {x}->{y} b=5", trend({"/a":[x]*10+[y]*10, "/b":[5]*20}))
for c in [1,5,10,50]:
    print(f"a 1->10 b={c}", trend({"/a":[1]*10+[10]*10, "/b":[c]*20}))
PY
"}

