import pty, os, subprocess, re, struct, fcntl, termios
def run_pty(args, cols):
    master, slave = pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH", 50, cols, 0,0))
    p=subprocess.Popen(args, stdout=slave, stderr=slave, stdin=subprocess.DEVNULL, close_fds=True)
    os.close(slave)
    out=b""
    while True:
        try:
            d=os.read(master, 65536)
            if not d: break
            out+=d
        except OSError:
            break
    p.wait(); os.close(master)
    return out.decode(errors='replace')
ansi=re.compile(r'\x1b\[[0-9;]*m|\x1b7|\x1b8|\x1b\[2K|\r')
