import datetime, subprocess
def trend_from_series(a_counts,b_counts):
    lines=[]
    base=datetime.date(2021,1,1)
    for idx,(a,b) in enumerate(zip(a_counts,b_counts)):
        d=base+datetime.timedelta(days=idx); ds=d.strftime("%d/%b/%Y")
        for _ in range(a): lines.append(f'10.0.0.1 - - [{ds}:06:00:00 +0000] "GET /a HTTP/1.1" 200 100 "-" "UA"')
        for _ in range(b): lines.append(f'10.0.0.1 - - [{ds}:06:00:00 +0000] "GET /b HTTP/1.1" 200 100 "-" "UA"')
    open("/tmp/t/tmp.log","w").write("\n".join(lines)+"\n")
    r=subprocess.run(["./executable","--color","no","--silent-load","-f","path","/tmp/t/tmp.log"],capture_output=True,text=True)
    out={}
    for l in r.stdout.splitlines():
        p=l.split('│')
        if len(p)>=7 and p[2].strip() in ("/a","/b"): out[p[2].strip()]=p[6].strip()
    return out

# two halves: first 10 days A=x,B=10-x ; last 10 days A=y,B=10-y
for x,y in [(1,9),(9,1),(1,5),(5,1),(2,8),(8,2),(1,10),(10,1),(0,10),(10,0),(5,10),(10,5)]:
