use std::cmp::Ordering;
use std::fmt;

#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
pub struct Date {
    pub year: u16,
    pub month: u8,
    pub day: u8,
}
impl Date {
    pub fn new(year: u16, month: u8, day: u8) -> Result<Self, DateTimeError> {
        // validation order as observed: day first, then month
        if day == 0 || day > 31 {
            return Err(DateTimeError::InvalidDay(day));
        }
        if month == 0 || month > 12 {
            return Err(DateTimeError::InvalidMonth(month));
        }
        Ok(Self { year, month, day })
    }
}
impl fmt::Display for Date {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}/{:02}/{:02}", self.year, self.month, self.day)
    }
}
impl PartialOrd for Date {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> { Some(self.cmp(other)) }
}
impl Ord for Date {
    fn cmp(&self, other: &Self) -> Ordering {
        (self.year, self.month, self.day).cmp(&(other.year, other.month, other.day))
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
pub struct Time {
    pub hour: u8,
    pub minute: u8,
    pub second: u8,
}
impl Time {
    pub fn new(hour: u8, minute: u8, second: u8) -> Result<Self, TimeError> {
        if hour > 23 { return Err(TimeError::InvalidHour(hour)); }
        if minute > 59 { return Err(TimeError::InvalidMinute(minute)); }
        if second > 59 { return Err(TimeError::InvalidSecond(second)); }
        Ok(Self { hour, minute, second })
    }
    pub fn seconds(&self) -> u32 { self.hour as u32 * 3600 + self.minute as u32 * 60 + self.second as u32 }
}
impl fmt::Display for Time {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{:02}:{:02}:{:02}", self.hour, self.minute, self.second)
    }
}
impl PartialOrd for Time {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> { Some(self.cmp(other)) }
}
impl Ord for Time {
    fn cmp(&self, other: &Self) -> Ordering {
        (self.hour, self.minute, self.second).cmp(&(other.hour, other.minute, other.second))
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
pub struct DateTime {
    pub date: Date,
    pub time: Time,
}
impl PartialOrd for DateTime {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> { Some(self.cmp(other)) }
}
impl Ord for DateTime {
    fn cmp(&self, other: &Self) -> Ordering {
        (self.date, self.time).cmp(&(other.date, other.time))
    }
}

#[derive(Debug)]
pub enum DateTimeError {
    IntExpected(std::num::ParseIntError),
    InvalidMonth(u8),
    InvalidDay(u8),
    InvalidHour(u8),
    InvalidMinute(u8),
    InvalidSecond(u8),
}
#[derive(Debug)]
pub enum TimeError {
    IntExpected(std::num::ParseIntError),
    UnexpectedEnd,
    InvalidHour(u8),
    InvalidMinute(u8),
    InvalidSecond(u8),
}

pub fn parse_u8(tok: &str) -> Result<u8, DateTimeError> {
    tok.parse::<u8>().map_err(DateTimeError::IntExpected)
}
pub fn parse_u16(tok: &str) -> Result<u16, DateTimeError> {
    tok.parse::<u16>().map_err(DateTimeError::IntExpected)
}

// month name from log
pub fn month_from_name(s: &str) -> Option<u8> {
    match s {
        "Jan" => Some(1), "Feb" => Some(2), "Mar" => Some(3), "Apr" => Some(4),
        "May" => Some(5), "Jun" => Some(6), "Jul" => Some(7), "Aug" => Some(8),
        "Sep" => Some(9), "Oct" => Some(10), "Nov" => Some(11), "Dec" => Some(12),
        _ => None,
    }
}

/// Parse the datetime found inside [...] of a log line.
/// Expects the start of `s` to be DD/Mon/YYYY:HH:MM:SS (fixed positions)
/// and ignores any trailing content.
pub fn parse_log_datetime(s: &str) -> Option<DateTime> {
    let b = s.as_bytes();
    if b.len() < 20 { return None; }
    // check separators loosely but positions must be digits where expected
    if b[2] != b'/' || b[6] != b'/' || b[11] != b':' || b[14] != b':' || b[17] != b':' { return None; }
    let day_s = &s[0..2];
    let mon_s = &s[3..6];
    let year_s = &s[7..11];
    let hour_s = &s[12..14];
    let min_s = &s[15..17];
    let sec_s = &s[18..20];
    if !day_s.bytes().all(|c| c.is_ascii_digit()) || !year_s.bytes().all(|c| c.is_ascii_digit())
        || !hour_s.bytes().all(|c| c.is_ascii_digit()) || !min_s.bytes().all(|c| c.is_ascii_digit())
        || !sec_s.bytes().all(|c| c.is_ascii_digit()) { return None; }
    let month = month_from_name(mon_s)?;
    let day: u8 = day_s.parse().ok()?;
    let year: u16 = year_s.parse().ok()?;
    let hour: u8 = hour_s.parse().ok()?;
    let minute: u8 = min_s.parse().ok()?;
    let second: u8 = sec_s.parse().ok()?;
    if day == 0 || day > 31 || hour > 23 || minute > 59 || second > 59 { return None; }
    Some(DateTime {
        date: Date { year, month, day },
        time: Time { hour, minute, second },
    })
}
