// month name from log
pub fn month_from_name(s: &str) -> Option<u8> {
    match s {
        "Jan" => Some(1), "Feb" => Some(2), "Mar" => Some(3), "Apr" => Some(4),
        "May" => Some(5), "Jun" => Some(6), "Jul" => Some(7), "Aug" => Some(8),
        "Sep" => Some(9), "Oct" => Some(10), "Nov" => Some(11), "Dec" => Some(12),
        _ => None,
    }
}

/// Parse the datetime found inside [...] of a log line.
/// Expects the start of `s` to be DD/Mon/YYYY:HH:MM:SS (fixed positions)
/// and ignores any trailing content.
pub fn parse_log_datetime(s: &str) -> Option<DateTime> {
    let b = s.as_bytes();
    if b.len() < 20 { return None; }
    // check separators loosely but positions must be digits where expected
    if b[2] != b'/' || b[6] != b'/' || b[11] != b':' || b[14] != b':' || b[17] != b':' { return None; }
    let day_s = &s[0..2];
    let mon_s = &s[3..6];
    let year_s = &s[7..11];
    let hour_s = &s[12..14];
    let min_s = &s[15..17];
    let sec_s = &s[18..20];
    if !day_s.bytes().all(|c| c.is_ascii_digit()) || !year_s.bytes().all(|c| c.is_ascii_digit())
        || !hour_s.bytes().all(|c| c.is_ascii_digit()) || !min_s.bytes().all(|c| c.is_ascii_digit())
        || !sec_s.bytes().all(|c| c.is_ascii_digit()) { return None; }
    let month = month_from_name(mon_s)?;
    let day: u8 = day_s.parse().ok()?;
    let year: u16 = year_s.parse().ok()?;
    let hour: u8 = hour_s.parse().ok()?;
    let minute: u8 = min_s.parse().ok()?;
    let second: u8 = sec_s.parse().ok()?;
    if day == 0 || day > 31 || hour > 23 || minute > 59 || second > 59 { return None; }
    Some(DateTime {
        date: Date { year, month, day },
        time: Time { hour, minute, second },
    })
}
