use crate::datetime::*;
use regex::Regex;

// ---------- DateTime filter ----------
#[derive(Clone, Copy, PartialEq)]
enum Precision { Year, Month, Day }

#[derive(Clone)]
struct PartialDt {
    date: Date,
    precision: Precision,
    time: Option<Time>,
}
#[derive(Clone)]
pub enum DateTimeFilter {
    Exact(PartialDt),
    Not(Date, Option<Time>),
    After(Date, Option<Time>),
    Before(Date, Option<Time>),
    Range(DateTime, DateTime),
}

fn split_dt(s: &str) -> (String, Option<String>) {
    if let Some(idx) = s.find('T') {
        return (s[..idx].to_string(), Some(s[idx + 1..].to_string()));
    }
    // space separator before a time token containing ':'
    let bytes = s.as_bytes();
    for i in 0..bytes.len() {
        if bytes[i] == b' ' {
            let rest = &s[i + 1..];
            if rest.contains(':') && rest.chars().next().map(|c| c.is_ascii_digit()).unwrap_or(false) {
                // only treat as separator if the date part has a '/' or has at most 3 tokens
                return (s[..i].to_string(), Some(rest.to_string()));
            }
        }
    }
    (s.to_string(), None)
}

fn tokens_of(s: &str) -> Vec<String> {
    s.split(|c: char| !c.is_ascii_digit()).map(|t| t.to_string()).collect()
}

fn make_time_filter_err(h: u8, m: u8, sec: u8) -> Result<Time, DateTimeError> {
    if h > 23 { return Err(DateTimeError::InvalidHour(h)); }
    if m > 59 { return Err(DateTimeError::InvalidMinute(m)); }
    if sec > 59 { return Err(DateTimeError::InvalidSecond(sec)); }
    Ok(Time { hour: h, minute: m, second: sec })
}

fn parse_time_tokens(toks: &[String], validate_second: bool) -> Result<Time, DateTimeError> {
    let h = if toks.is_empty() { parse_u8("")? } else { parse_u8(&toks[0])? };
    let m = if toks.len() > 1 { parse_u8(&toks[1])? } else { 0 };
    let sec = if toks.len() > 2 { parse_u8(&toks[2])? } else { 0 };
    if validate_second { make_time_filter_err(h, m, sec) } else {
        if h > 23 { return Err(DateTimeError::InvalidHour(h)); }
        if m > 59 { return Err(DateTimeError::InvalidMinute(m)); }
        Ok(Time { hour: h, minute: m, second: sec })
    }
}

fn parse_concrete(s: &str, reference: DateTime) -> Result<(Date, Option<Time>), DateTimeError> {
    let (date_str, time_str) = split_dt(s);
    let toks = tokens_of(&date_str);
    // date construction
    let date: Date = match toks.len() {
        1 => {
            let d = parse_u8(&toks[0])?;
            Date::new(reference.date.year, reference.date.month, d)?
        }
        2 => {
            let mo = parse_u8(&toks[0])?;
            let d = parse_u8(&toks[1])?;
            Date::new(reference.date.year, mo, d)?
        }
        _ => {
            // 3 or more: first three are YMD (extra tokens ignored unless no time part)
            let y = parse_u16(&toks[0])?;
            let mo = parse_u8(&toks[1])?;
            let d = parse_u8(&toks[2])?;
            let dt = Date::new(y, mo, d)?;
            if time_str.is_none() && toks.len() > 3 {
                // sequential fallback: tokens after date are H:M:S
                let tt = parse_time_tokens(&toks[3..].to_vec(), true)?;
                return Ok((dt, Some(tt)));
            }
            dt
        }
    };
    let time = match time_str {
        Some(ts) => {
            let ttoks = tokens_of(&ts);
            Some(parse_time_tokens(&ttoks, true)?)
        }
        None => None,
    };
    Ok((date, time))
}

fn parse_partial(s: &str, reference: DateTime) -> Result<PartialDt, DateTimeError> {
    let (date_str, time_str) = split_dt(s);
    let toks = tokens_of(&date_str);
    let (y_opt, m_opt, d_opt, precision) = match toks.len() {
        1 => {
            if toks[0].len() == 4 {
                (Some(parse_u16(&toks[0])?), None, None, Precision::Year)
            } else {
                (None, None, Some(parse_u8(&toks[0])?), Precision::Day)
            }
        }
        2 => {
            if toks[0].len() == 4 {
                let y = parse_u16(&toks[0])?;
                let mo = parse_u8(&toks[1])?;
                (Some(y), Some(mo), None, Precision::Month)
            } else {
                let mo = parse_u8(&toks[0])?;
                let d = parse_u8(&toks[1])?;
                (None, Some(mo), Some(d), Precision::Day)
            }
        }
        _ => {
            let y = parse_u16(&toks[0])?;
            // if there are not enough tokens, this will panic on index; guard
            let mo = if toks.len() > 1 { parse_u8(&toks[1])? } else { parse_u8("")? };
            let d = if toks.len() > 2 { parse_u8(&toks[2])? } else { parse_u8("")? };
            (Some(y), Some(mo), Some(d), Precision::Day)
        }
    };
    let year = y_opt.unwrap_or(reference.date.year);
    let month = m_opt.unwrap_or(reference.date.month);
    let day = d_opt.unwrap_or(reference.date.day);
    let date = Date::new(year, month, day)?;
    let time = match time_str {
        Some(ts) => {
            let ttoks = tokens_of(&ts);
            Some(parse_time_tokens(&ttoks, true)?)
        }
        None => None,
    };
    Ok(PartialDt { date, precision, time })
}

impl DateTimeFilter {
    pub fn parse(s: &str, reference: DateTime) -> Result<Self, DateTimeError> {
        let mut chars = s.chars();
        match chars.next() {
            Some('>') => {
                let rest = &s[1..];
                let (date, time) = parse_concrete(rest.trim_start(), reference)?;
                Ok(DateTimeFilter::After(date, time))
            }
            Some('<') => {
                let rest = &s[1..];
                let (date, time) = parse_concrete(rest.trim_start(), reference)?;
                Ok(DateTimeFilter::Before(date, time))
            }
            Some('!') => {
                let rest = &s[1..];
                let (date, time) = parse_concrete(rest.trim_start(), reference)?;
                Ok(DateTimeFilter::Not(date, time))
            }
            _ => {
                if s.contains('-') {
                    let mut parts = s.split('-');
                    let a = parts.next().unwrap_or("");
                    let b = parts.next().unwrap_or("");
                    let (d1, t1) = parse_concrete(a.trim(), reference)?;
                    let (d2, t2) = parse_concrete(b.trim(), reference)?;
                    let start = DateTime { date: d1, time: t1.unwrap_or(Time { hour: 0, minute: 0, second: 0 }) };
                    let end = match t2 {
                        Some(t) => DateTime { date: d2, time: t },
                        None => DateTime { date: d2, time: Time { hour: 23, minute: 59, second: 59 } },
                    };
                    Ok(DateTimeFilter::Range(start, end))
                } else {
                    Ok(DateTimeFilter::Exact(parse_partial(s, reference)?))
                }
            }
        }
    }
    pub fn accepts(&self, dt: DateTime) -> bool {
        match self {
            DateTimeFilter::Exact(p) => {
                if let Some(t) = p.time {
                    dt == DateTime { date: p.date, time: t }
                } else {
                    match p.precision {
                        Precision::Year => dt.date.year == p.date.year,
                        Precision::Month => dt.date.year == p.date.year && dt.date.month == p.date.month,
                        Precision::Day => dt.date == p.date,
                    }
                }
            }
            DateTimeFilter::Not(date, time) => {
                match time {
                    Some(t) => dt != DateTime { date: *date, time: *t },
                    None => dt.date != *date,
                }
            }
            DateTimeFilter::After(date, time) => {
                match time {
                    Some(t) => dt > DateTime { date: *date, time: *t },
                    None => dt.date > *date,
                }
            }
            DateTimeFilter::Before(date, time) => {
                match time {
                    Some(t) => dt < DateTime { date: *date, time: *t },
                    None => dt.date < *date,
                }
            }
            DateTimeFilter::Range(a, b) => dt >= *a && dt <= *b,
        }
    }
}

// ---------- Time filter ----------
#[derive(Debug)]
pub enum TimeFilterError {
    InvalidFormat,
    TimeParse(TimeError),
}
pub enum TimeFilter {
    After(Time),
    Before(Time),
    Range(Time, Time),
}
fn parse_time_str(s: &str) -> Result<Time, TimeError> {
    let b = s.as_bytes();
    if b.len() < 2 { return Err(TimeError::UnexpectedEnd); }
    let hour_str = &s[0..2];
    let hour: u8 = hour_str.parse::<u8>().map_err(TimeError::IntExpected)?;
    if hour > 23 { return Err(TimeError::InvalidHour(hour)); }
    if b.len() == 2 { return Ok(Time { hour, minute: 0, second: 0 }); }
    // minute
    let minute: u8 = if b.len() == 3 {
        0
    } else {
        let mstr = if b.len() >= 5 { &s[3..5] } else { &s[3..] };
        if mstr.is_empty() { 0 } else { mstr.parse::<u8>().map_err(TimeError::IntExpected)? }
    };
    if minute > 59 { return Err(TimeError::InvalidMinute(minute)); }
    if b.len() <= 5 { return Ok(Time { hour, minute, second: 0 }); }
    let sec: u8 = if b.len() == 6 {
        0
    } else {
        let sstr = if b.len() >= 8 { &s[6..8] } else { &s[6..] };
        if sstr.is_empty() { 0 } else { sstr.parse::<u8>().map_err(TimeError::IntExpected)? }
    };
    // seconds deliberately not range-validated (observed)
    Ok(Time { hour, minute, second: sec })
}
impl TimeFilter {
    pub fn parse(s: &str) -> Result<Self, TimeFilterError> {
        if let Some(rest) = s.strip_prefix('>') {
            Ok(TimeFilter::After(parse_time_str(rest.trim_start()).map_err(TimeFilterError::TimeParse)?))
        } else if let Some(rest) = s.strip_prefix('<') {
            Ok(TimeFilter::Before(parse_time_str(rest.trim_start()).map_err(TimeFilterError::TimeParse)?))
        } else if s.contains('-') {
            let mut parts = s.split('-');
            let a = parts.next().unwrap_or("");
            let b = parts.next().unwrap_or("");
            let t1 = parse_time_str(a.trim()).map_err(TimeFilterError::TimeParse)?;
            let t2 = parse_time_str(b.trim()).map_err(TimeFilterError::TimeParse)?;
            Ok(TimeFilter::Range(t1, t2))
        } else {
            Err(TimeFilterError::InvalidFormat)
        }
    }
    pub fn accepts(&self, t: Time) -> bool {
        match self {
            TimeFilter::After(f) => t > *f,
            TimeFilter::Before(f) => t < *f,
            TimeFilter::Range(a, b) => t >= *a && t <= *b,
        }
    }
}

// ---------- Status filter ----------
#[derive(Debug)]
pub enum StatusFilterError {
    ParseInt(std::num::ParseIntError),
}
enum StatusCond { Exact(u16), Range(u16, u16) }
pub struct StatusFilter {
    conds: Vec<(bool, StatusCond)>, // (negated, cond)
}
impl StatusFilter {
    pub fn parse(s: &str) -> Result<Self, StatusFilterError> {
        let mut conds = Vec::new();
        for raw in s.split(',') {
            let tok = raw.trim();
            let (neg, body) = if let Some(rest) = tok.strip_prefix('!') {
                (true, rest.trim())
            } else { (false, tok) };
            let cond = match body {
                "2xx" => StatusCond::Range(200, 299),
                "3xx" => StatusCond::Range(300, 399),
                "4xx" => StatusCond::Range(400, 499),
                "5xx" => StatusCond::Range(500, 599),
                _ => {
                    if body.contains('-') {
                        let mut it = body.split('-');
                        let a = it.next().unwrap_or("");
                        let b = it.next().unwrap_or("");
                        let av: u16 = a.parse().map_err(StatusFilterError::ParseInt)?;
                        let bv: u16 = b.parse().map_err(StatusFilterError::ParseInt)?;
                        StatusCond::Range(av, bv)
                    } else {
                        let v: u16 = body.parse().map_err(StatusFilterError::ParseInt)?;
                        StatusCond::Exact(v)
                    }
                }
            };
            conds.push((neg, cond));
        }
        Ok(StatusFilter { conds })
    }
    fn cond_matches(c: &StatusCond, status: u16) -> bool {
        match c { StatusCond::Exact(v) => status == *v, StatusCond::Range(a, b) => status >= *a && status <= *b }
    }
    pub fn accepts(&self, status: u16) -> bool {
        let mut has_pos = false;
        let mut pos_ok = false;
        for (neg, c) in &self.conds {
            if *neg {
                if Self::cond_matches(c, status) { return false; }
            } else {
                has_pos = true;
                if Self::cond_matches(c, status) { pos_ok = true; }
            }
        }
        !has_pos || pos_ok
    }
}

// ---------- Method ----------
#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
pub enum Method {
    Get, Post, Put, Delete, Head, Options, Patch, Connect, Trace, Other, None,
}
impl Method {
    pub fn from_token(tok: &str) -> Self {
        match tok {
            "GET" => Method::Get, "POST" => Method::Post, "PUT" => Method::Put,
            "DELETE" => Method::Delete, "HEAD" => Method::Head, "OPTIONS" => Method::Options,
            "PATCH" => Method::Patch, "CONNECT" => Method::Connect, "TRACE" => Method::Trace,
            "none" | "" => Method::None,
            _ => Method::Other,
        }
    }
    pub fn name(&self) -> &'static str {
        match self {
            Method::Get => "GET", Method::Post => "POST", Method::Put => "PUT",
            Method::Delete => "DELETE", Method::Head => "HEAD", Method::Options => "OPTIONS",
            Method::Patch => "PATCH", Method::Connect => "CONNECT", Method::Trace => "TRACE",
            Method::Other => "other", Method::None => "none",
        }
    }
}
pub struct MethodFilter { negated: bool, method: Method }
impl MethodFilter {
    pub fn parse(s: &str) -> Self {
        if let Some(rest) = s.strip_prefix('!') {
            MethodFilter { negated: true, method: Method::from_token(rest) }
        } else {
            MethodFilter { negated: false, method: Method::from_token(s) }
        }
    }
    pub fn accepts(&self, m: Method) -> bool {
        (m == self.method) != self.negated
    }
}

// ---------- String filter (path / referer / ip) ----------
#[derive(Debug)]
pub enum StrFilterError {
    InvalidRegex(regex::Error),
    InvalidPattern(String, &'static str),
    // second field messages are matched dynamically; we store a String in a wrapper below if needed
    InvalidPatternMsg(String, String),
}
pub enum StrFilter {
    Regex { negated: bool, re: Regex },
    And(Vec<StrFilter>),
    Or(Vec<StrFilter>),
    Not(Box<StrFilter>),
    True,
    False,
}
fn regex_new(p: &str) -> Result<Regex, StrFilterError> {
    Regex::new(p).map_err(StrFilterError::InvalidRegex)
}
impl StrFilter {
    pub fn from_str(s: &str) -> Result<Self, StrFilterError> {
        if s.contains(',') {
            return Self::parse_comma(s);
        }
        if s.contains(' ') {
            return Self::parse_expression(s);
        }
        Self::parse_simple(s)
    }
    fn parse_simple(s: &str) -> Result<Self, StrFilterError> {
        if !s.is_empty() && s.chars().all(|c| c == '!') {
            return Ok(StrFilter::True);
        }
        if let Some(rest) = s.strip_prefix('!') {
            return Ok(StrFilter::Not(Box::new(Self::parse_simple(rest)?)));
        }
        Ok(StrFilter::Regex { negated: false, re: regex_new(s)? })
    }
    fn parse_comma(s: &str) -> Result<Self, StrFilterError> {
        #[derive(Clone)]
        struct Token { negated: bool, re: Regex }
        let mut tokens: Vec<Token> = Vec::new();
        for raw in s.split(',') {
            let tok = raw.trim();
            if tok.is_empty() {
                return Err(StrFilterError::InvalidPattern(s.to_string(), "empty token"));
            }
            if let Some(rest) = tok.strip_prefix('!') {
                tokens.push(Token { negated: true, re: regex_new(rest)? });
            } else {
                tokens.push(Token { negated: false, re: regex_new(tok)? });
            }
        }
        // wrap tokens into a special filter using And of Regex nodes with negated flags
        let filters = tokens.into_iter().map(|t| StrFilter::Regex { negated: t.negated, re: t.re }).collect();
        Ok(StrFilter::And(filters))
    }
    fn parse_expression(s: &str) -> Result<Self, StrFilterError> {
        let tokens: Vec<String> = s.split_whitespace().map(|t| t.to_string()).collect();
        let mut parser = ExprParser { tokens, pos: 0, pattern: s.to_string() };
        parser.parse_top()
    }
    pub fn accepts(&self, text: &str) -> bool {
        match self {
            StrFilter::Regex { negated, re } => re.is_match(text) != *negated,
            StrFilter::And(v) => v.iter().all(|f| f.accepts(text)),
            StrFilter::Or(v) => v.iter().any(|f| f.accepts(text)),
            StrFilter::Not(f) => !f.accepts(text),
            StrFilter::True => true,
            StrFilter::False => false,
        }
    }
}

struct ExprParser {
    tokens: Vec<String>,
    pos: usize,
    pattern: String,
}
impl ExprParser {
    fn err(&self, msg: &'static str) -> StrFilterError {
        StrFilterError::InvalidPattern(self.pattern.clone(), msg)
    }
    fn peek(&self) -> Option<&str> { self.tokens.get(self.pos).map(|s| s.as_str()) }
    fn parse_top(&mut self) -> Result<StrFilter, StrFilterError> {
        let f = self.parse_expr()?;
        // trailing tokens that are not operators: ignore (observed for trailing groups etc.)
        Ok(f)
    }
    fn parse_expr(&mut self) -> Result<StrFilter, StrFilterError> {
        let mut left = self.parse_operand()?;
        loop {
            match self.peek() {
                None => break,
                Some("&") | Some("|") => {
                    let op = self.peek().unwrap().to_string();
                    // trailing operator: fold into rightmost leaf
                    if self.pos == self.tokens.len() - 1 {
                        Self::extend_rightmost(&mut left, &format!(" {}", op));
                        self.pos += 1;
                        break;
                    }
                    // check next token for operator/closing errors
                    let next = self.tokens.get(self.pos + 1).map(|s| s.as_str());
                    match next {
                        Some("&") => return Err(self.err("unexpected '&'")),
                        Some("|") => return Err(self.err("unexpected '|'")),
                        Some(")") => return Err(self.err("unexpected closing parenthesis")),
                        _ => {}
                    }
                    self.pos += 1;
                    // operand parse; may panic like original on missing operand (e.g. "a & !")
                    let right = self.parse_operand()?;
                    left = if op == "&" { StrFilter::And(vec![left, right]) } else { StrFilter::Or(vec![left, right]) };
                }
                Some("(") | Some("!(") => {
                    return Err(self.err("unexpected opening parenthesis"));
                }
                Some(")") => {
                    // let caller (group) handle; at top-level it's an error handled by caller checks
                    break;
                }
                Some(_) => {
                    // adjacency: extend rightmost leaf if it's a simple regex, else skip word tokens
                    let tok = self.peek().unwrap().to_string();
                    if Self::extend_rightmost(&mut left, &format!(" {}", tok)) {
                        self.pos += 1;
                    } else {
                        self.pos += 1;
                    }
                }
            }
        }
        Ok(left)
    }
    fn extend_rightmost(f: &mut StrFilter, suffix: &str) -> bool {
        match f {
            StrFilter::Regex { negated, re } => {
                // We do not have the raw pattern; extending via a new regex built from
                // the old pattern string is possible through re.as_str()
                let raw = re.as_str().to_string();
                let new_raw = format!("{}{}", raw, suffix);
                match Regex::new(&new_raw) {
                    Ok(nre) => { *re = nre; true }
                    Err(_) => false,
                }
            }
            StrFilter::And(v) | StrFilter::Or(v) => {
                if let Some(last) = v.last_mut() { Self::extend_rightmost(last, suffix) } else { false }
            }
            StrFilter::Not(inner) => Self::extend_rightmost(inner, suffix),
            _ => false,
        }
    }
    fn parse_operand(&mut self) -> Result<StrFilter, StrFilterError> {
        match self.peek() {
            None => {
                panic!("unexpected operator or operands");
            }
            Some("&") => Err(self.err("unexpected '&'")),
            Some("|") => Err(self.err("unexpected '|'")),
            Some(")") => Err(self.err("unexpected closing parenthesis")),
            Some("(") => {
                self.pos += 1;
                // group: parse an expression until ) or end
                if matches!(self.peek(), Some(")")) {
                    return Err(self.err("unexpected closing parenthesis"));
                }
                let inner = self.parse_expr()?;
                if matches!(self.peek(), Some(")")) { self.pos += 1; }
                Ok(inner)
            }
            Some("!(") => {
                self.pos += 1;
                if matches!(self.peek(), Some(")")) {
                    return Err(self.err("unexpected closing parenthesis"));
                }
                let inner = self.parse_expr()?;
                if matches!(self.peek(), Some(")")) { self.pos += 1; }
                Ok(StrFilter::Not(Box::new(inner)))
            }
            Some("!") => {
                self.pos += 1;
                let inner = self.parse_operand()?;
                Ok(StrFilter::Not(Box::new(inner)))
            }
            Some(_) => {
                // leaf chunk: consecutive word tokens
                let mut negated_count = 0usize;
                let mut first = true;
                let mut raw = String::new();
                while let Some(tok) = self.peek() {
                    if tok == "&" || tok == "|" || tok == "(" || tok == ")" || tok == "!(" { break; }
                    let tok = tok.to_string();
                    self.pos += 1;
                    if first {
                        // strip leading ! chars from first token, toggling
                        let mut t = tok.as_str();
                        while let Some(rest) = t.strip_prefix('!') {
                            negated_count += 1;
                            t = rest;
                        }
                        raw = t.to_string();
                        first = false;
                    } else {
                        if !raw.is_empty() { raw.push(' '); }
                        raw.push_str(&tok);
                    }
                }
                let re = regex_new(&raw)?;
                let mut f = StrFilter::Regex { negated: false, re };
                if negated_count % 2 == 1 { f = StrFilter::Not(Box::new(f)); }
                Ok(f)
            }
        }
    }
}
RS
echo done
"}

