use crate::datetime::*;
use crate::filters::Method;

#[derive(Clone, Debug)]
pub struct Hit {
    pub datetime: DateTime,
    pub remote_addr: String,
    pub method: Method,
    pub path: String,
    pub status: u16,
    pub bytes_sent: u64,
    pub referer: String,
}

pub fn parse_line(line: &str) -> Option<Hit> {
    // line may end with \n and/or \r (from read_line); parsing is tolerant at end
    let s = line.strip_suffix('\n').unwrap_or(line);
    // remote addr: until first space
    let sp = s.find(' ')?;
    let remote_addr = &s[..sp];
    let rest = &s[sp + 1..];
    let lb = rest.find('[')?;
    let rb = rest[lb + 1..].find(']')? + lb + 1;
    let dt_str = &rest[lb + 1..rb];
    let datetime = parse_log_datetime(dt_str)?;
    let after = &rest[rb + 1..];
    let q1 = after.find('"')?;
    let q2 = after[q1 + 1..].find('"')? + q1 + 1;
    let request = &after[q1 + 1..q2];
    let suffix = &after[q2 + 1..];
    // suffix must be " STATUS BYTES ..."
    let mut it = suffix.splitn(2, ' ');
    let first = it.next()?;
    if !first.is_empty() { return None; }
    let rem = it.next()?;
    let sp2 = rem.find(' ')?;
    let status_s = &rem[..sp2];
    let status: u16 = status_s.parse().ok()?;
    let rem2 = &rem[sp2 + 1..];
    // bytes token is up to next space (or end)
    let bytes_end = rem2.find(' ').unwrap_or(rem2.len());
    let bytes_s = &rem2[..bytes_end];
    let bytes_sent: u64 = bytes_s.parse().ok()?;
    let after_bytes = &rem2[bytes_end..];
    let r1 = after_bytes.find('"')?;
    let r2 = after_bytes[r1 + 1..].find('"')? + r1 + 1;
    let referer = &after_bytes[r1 + 1..r2];
    // request parsing
    let mut parts = request.split(' ');
    let first_tok = parts.next().unwrap_or("");
    let (method, path_raw) = match parts.next() {
        None => (Method::None, request),
        Some(p) => (Method::from_token(first_tok), p),
    };
    let path = path_raw.split('?').next().unwrap_or("").to_string();
    Some(Hit {
        datetime,
        remote_addr: remote_addr.to_string(),
        method,
        path,
        status,
        bytes_sent,
        referer: referer.to_string(),
    })
}
RS
echo ok
"}

