// Render styled characters grouped by *segment boundaries*: we keep segment index
fn render_styled_chars(mode: Mode, chars: &[(char, Option<Style>, usize)]) -> String {
    // chars: (char, style, segment_id)
    let mut out = String::new();
    let mut i = 0;
    while i < chars.len() {
        let (_, style, seg) = chars[i];
        let mut j = i;
        let mut txt = String::new();
        while j < chars.len() && chars[j].1 == style && chars[j].2 == seg {
            txt.push(chars[j].0);
            j += 1;
        }
        match style {
            Some(st) => out.push_str(&mode.styled(st, &txt)),
            None => out.push_str(&txt),
        }
        i = j;
    }
    out
}

fn pad_line(mode: Mode, line_chars: &[(char, Option<Style>, usize)], width: usize, align: Align) -> String {
    let w: usize = line_chars.iter().map(|(c, _, _)| char_width(*c)).sum();
    let pad = width.saturating_sub(w);
    let (left, right) = match align {
        Align::Left => (0, pad),
        Align::Right => (pad, 0),
        Align::Center => (pad / 2, pad - pad / 2),
    };
    let mut out = String::new();
    out.push_str(&" ".repeat(left));
    out.push_str(&render_styled_chars(mode, line_chars));
    out.push_str(&" ".repeat(right));
    out
}

// A word for wrapping: Vec of styled chars
type SChar = (char, Option<Style>, usize);

fn wrap_paragraph_chars(chars: &[SChar], width: usize) -> Vec<Vec<SChar>> {
    // split words by spaces
    #[derive(Clone)]
    struct Word { chars: Vec<SChar> }
    let mut words: Vec<Word> = Vec::new();
    let mut cur: Vec<SChar> = Vec::new();
    for ch in chars {
        if ch.0 == ' ' {
            if !cur.is_empty() { words.push(Word { chars: std::mem::take(&mut cur) }); }
        } else {
            cur.push(*ch);
        }
    }
    if !cur.is_empty() { words.push(Word { chars: cur }); }
    if words.is_empty() { return vec![Vec::new()]; }
    let mut lines: Vec<Vec<SChar>> = Vec::new();
    let mut line: Vec<SChar> = Vec::new();
    let mut line_w = 0usize;
    let word_width = |w: &Word| -> usize { w.chars.iter().map(|(c, _, _)| char_width(*c)).sum() };
    for word in words {
        let ww = word_width(&word);
        if ww > width && width > 0 {
            // flush current line
            if !line.is_empty() {
                lines.push(std::mem::take(&mut line));
                line_w = 0;
            }
            // cut the word into chunks
            let mut chunk: Vec<SChar> = Vec::new();
            let mut cw = 0usize;
            for ch in word.chars {
                let chw = char_width(ch.0);
                if cw + chw > width && !chunk.is_empty() {
                    lines.push(std::mem::take(&mut chunk));
                    cw = 0;
                }
                chunk.push(ch);
                cw += chw;
            }
            if !chunk.is_empty() {
                line = chunk;
                line_w = cw;
            }
            continue;
        }
        if line.is_empty() {
            line = word.chars.clone();
            line_w = ww;
        } else if line_w + 1 + ww <= width {
            line.push((' ', None, usize::MAX));
            line.extend(word.chars.iter().cloned());
            line_w += 1 + ww;
        } else {
            lines.push(std::mem::take(&mut line));
            line = word.chars.clone();
            line_w = ww;
        }
    }
    if !line.is_empty() || lines.is_empty() { lines.push(line); }
    lines
}

pub fn wrap_cell(cell: &Cell, width: usize, align: Align, mode: Mode) -> Vec<String> {
    // build SChar list with segment ids
    let mut chars: Vec<SChar> = Vec::new();
    for (seg_id, (s, st)) in cell.segments.iter().enumerate() {
        for c in s.chars() { chars.push((c, *st, seg_id)); }
    }
    let plain_w: usize = chars.iter().map(|(c, _, _)| char_width(*c)).sum();
    let mut out_lines: Vec<String> = Vec::new();
    if plain_w <= width {
        out_lines.push(pad_line(mode, &chars, width, align));
        return out_lines;
    }
    // split on explicit newlines first
    let mut paragraphs: Vec<Vec<SChar>> = Vec::new();
    let mut cur: Vec<SChar> = Vec::new();
    for ch in &chars {
        if ch.0 == '\n' {
            paragraphs.push(std::mem::take(&mut cur));
        } else { cur.push(*ch); }
    }
    paragraphs.push(cur);
    for para in &paragraphs {
        let pw: usize = para.iter().map(|(c, _, _)| char_width(*c)).sum();
        if pw <= width {
            out_lines.push(pad_line(mode, para, width, align));
        } else {
            for line in wrap_paragraph_chars(para, width) {
                out_lines.push(pad_line(mode, &line, width, align));
            }
        }
    }
    out_lines
}

pub fn wrap_paragraph(segments: &[(String, Option<Style>)], width: usize, mode: Mode) -> Vec<String> {
    let mut chars: Vec<SChar> = Vec::new();
    for (seg_id, (s, st)) in segments.iter().enumerate() {
        for c in s.chars() { chars.push((c, *st, seg_id)); }
    }
    let width = if width == 0 { 1 } else { width };
    // explicit newlines
    let mut paragraphs: Vec<Vec<SChar>> = Vec::new();
    let mut cur: Vec<SChar> = Vec::new();
    for ch in &chars {
        if ch.0 == '\n' { paragraphs.push(std::mem::take(&mut cur)); } else { cur.push(*ch); }
    }
    paragraphs.push(cur);
    let mut out: Vec<String> = Vec::new();
    for para in &paragraphs {
        let pw: usize = para.iter().map(|(c, _, _)| char_width(*c)).sum();
        if pw <= width {
            out.push(render_styled_chars(mode, para));
        } else {
            let lines = wrap_paragraph_chars(para, width);
            let n = lines.len();
            for (idx, line) in lines.iter().enumerate() {
                let mut s = render_styled_chars(mode, line);
                let lw: usize = line.iter().map(|(c, _, _)| char_width(*c)).sum();
                // trailing space on wrapped lines (except last) when it fits
                if idx + 1 < n && lw < width {
                    s.push(' ');
                }
                out.push(s);
            }
        }
    }
    out
}

pub struct Table {
    pub headers: Vec<Cell>,
    pub header_aligns: Vec<Align>,
    pub aligns: Vec<Align>,
    pub rows: Vec<Vec<Cell>>,
}

fn fit_widths(natural: &[usize], avail: usize) -> Vec<usize> {
    let n = natural.len();
    if n == 0 { return Vec::new(); }
    let borders = n + 1;
    let natural_total: usize = natural.iter().sum::<usize>() + borders;
    if natural_total <= avail { return natural.to_vec(); }
    let mut widths = natural.to_vec();
    // Reduce widest columns one by one; columns have a soft floor of 3,
    // but allow going below if still too wide.
    loop {
        let total: usize = widths.iter().sum::<usize>() + borders;
        if total <= avail { break; }
        // find widest column above 3
        let mut best: Option<usize> = None;
        for i in 0..n {
            if widths[i] > 3 {
                match best {
                    None => best = Some(i),
                    Some(b) => {
                        if widths[i] > widths[b] { best = Some(i); }
                    }
                }
            }
        }
        if best.is_none() {
            // allow below 3 down to 1
            let mut best2: Option<usize> = None;
            for i in 0..n {
                if widths[i] > 1 {
                    match best2 { None => best2 = Some(i), Some(b) => { if widths[i] > widths[b] { best2 = Some(i); } } }
                }
            }
            match best2 { Some(i) => widths[i] -= 1, None => break }
        } else {
            widths[best.unwrap()] -= 1;
        }
    }
    widths
}

impl Table {
    pub fn render(&self, avail: usize, mode: Mode) -> Vec<String> {
        let ncols = self.headers.len();
        if ncols == 0 { return Vec::new(); }
        let mut natural = vec![0usize; ncols];
        for i in 0..ncols {
            let mut w = text_width(&self.headers[i].text());
            for row in &self.rows {
                if i < row.len() { w = w.max(text_width(&row[i].text())); }
            }
            natural[i] = w.max(3);
        }
        let widths = fit_widths(&natural, avail);
        let mut out: Vec<String> = Vec::new();
        let border = |left: &str, join: &str, right: &str| -> String {
            let mut s = String::new();
            s.push_str(&mode.styled(Style::Gray, left));
            for (i, w) in widths.iter().enumerate() {
                s.push_str(&mode.styled(Style::Gray, &"─".repeat(*w)));
                if i + 1 < widths.len() {
                    s.push_str(&mode.styled(Style::Gray, join));
                }
            }
            s.push_str(&mode.styled(Style::Gray, right));
            s
        };
        out.push(border("┌", "┬", "┐"));
        // header
        let mut header_lines: Vec<Vec<String>> = Vec::new();
        let mut max_h = 0;
        for i in 0..ncols {
            let lines = wrap_cell(&self.headers[i], widths[i], self.header_aligns.get(i).cloned().unwrap_or(Align::Left), mode);
            max_h = max_h.max(lines.len());
            header_lines.push(lines);
        }
        for li in 0..max_h {
            let mut s = String::new();
            s.push_str(&mode.styled(Style::Gray, "│"));
            for i in 0..ncols {
                let txt = header_lines[i].get(li).cloned().unwrap_or_else(|| " ".repeat(widths[i]));
                s.push_str(&txt);
                s.push_str(&mode.styled(Style::Gray, "│"));
            }
            out.push(s);
        }
        out.push(border("├", "┼", "┤"));
        // rows
        for row in &self.rows {
            let mut cell_lines: Vec<Vec<String>> = Vec::new();
            let mut max_l = 0;
            for i in 0..ncols {
                let empty = Cell::plain("");
                let cell = row.get(i).unwrap_or(&empty);
                let lines = wrap_cell(cell, widths[i], self.aligns.get(i).cloned().unwrap_or(Align::Left), mode);
                max_l = max_l.max(lines.len());
                cell_lines.push(lines);
            }
            if max_l == 0 { max_l = 1; }
            for li in 0..max_l {
                let mut s = String::new();
                s.push_str(&mode.styled(Style::Gray, "│"));
                for i in 0..ncols {
                    let txt = cell_lines[i].get(li).cloned().unwrap_or_else(|| " ".repeat(widths[i]));
                    s.push_str(&txt);
                    s.push_str(&mode.styled(Style::Gray, "│"));
                }
                out.push(s);
            }
        }
        out.push(border("└", "┴", "┘"));
        out
    }
}
