cat > src/main.rs <<'RS'
mod datetime;
mod filters;
mod hit;
mod render;

use datetime::*;
use filters::*;
use hit::*;
use render::*;

use clap::{Arg, ArgAction, Command};
use flate2::read::GzDecoder;
use std::collections::HashMap;
use std::io::{BufRead, BufReader, IsTerminal, Read};
use std::path::Path;
use std::str::FromStr;

// ---------- errors ----------
#[derive(Debug)]
enum Error {
    PathNotFound(String),
    NoLogFileFound,
    Io(std::io::Error),
    DateTime(DateTimeError),
    StrFilter(StrFilterError),
    StatusFilter(StatusFilterError),
    TimeFilter(TimeFilterError),
}
impl From<std::io::Error> for Error {
    fn from(e: std::io::Error) -> Self { Error::Io(e) }
}

// ---------- CLI value types ----------
#[derive(Clone, Copy, PartialEq, Debug)]
enum Key { Hits, Bytes }
impl FromStr for Key {
    type Err = String;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s.to_lowercase().as_str() {
            "h" | "hit" | "hits" => Ok(Key::Hits),
            "b" | "byte" | "bytes" => Ok(Key::Bytes),
            _ => Err(format!("unrecognized key {:?}", s)),
        }
    }
}
#[derive(Clone, Copy, PartialEq, Debug)]
enum Output { Tables, Raw, Csv, Json }
impl FromStr for Output {
    type Err = String;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s.to_lowercase().as_str() {
            "t" | "tables" => Ok(Output::Tables),
            "r" | "raw" => Ok(Output::Raw),
            "c" | "csv" => Ok(Output::Csv),
            "j" | "json" => Ok(Output::Json),
            _ => Err(format!("unrecognized output {:?}", s)),
        }
    }
}
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Field { Dates, Times, Methods, Status, Ip, Referers, Paths }
const ALL_FIELDS: [Field; 7] = [Field::Dates, Field::Times, Field::Methods, Field::Status, Field::Ip, Field::Referers, Field::Paths];
const DEFAULT_FIELDS: [Field; 4] = [Field::Dates, Field::Status, Field::Referers, Field::Paths];

#[derive(Clone, Debug)]
struct Fields(Vec<Field>);
impl FromStr for Fields {
    type Err = String;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let mut list: Vec<Field> = Vec::new();
        let mut op_remove = false;
        let mut expect_start = true;
        let chars: Vec<char> = s.chars().collect();
        for (idx, c) in chars.iter().enumerate() {
            let c = *c;
            match c {
                '+' => {
                    if idx == 0 { list = DEFAULT_FIELDS.to_vec(); }
                    op_remove = false;
                    expect_start = true;
                }
                '-' => {
                    if idx == 0 { list = DEFAULT_FIELDS.to_vec(); }
                    op_remove = true;
                    expect_start = true;
                }
                ',' | ' ' => {
                    op_remove = false;
                    expect_start = true;
                }
                _ => {
                    if expect_start {
                        let lc = c.to_ascii_lowercase();
                        let apply = |list: &mut Vec<Field>, f: Field, remove: bool| {
                            if remove {
                                list.retain(|x| *x != f);
                            } else {
                                list.retain(|x| *x != f);
                                list.push(f);
                            }
                        };
                        match lc {
                            'd' => apply(&mut list, Field::Dates, op_remove),
                            't' => apply(&mut list, Field::Times, op_remove),
                            'm' => apply(&mut list, Field::Methods, op_remove),
                            's' => apply(&mut list, Field::Status, op_remove),
                            'i' => apply(&mut list, Field::Ip, op_remove),
                            'r' => apply(&mut list, Field::Referers, op_remove),
                            'p' => apply(&mut list, Field::Paths, op_remove),
                            'a' => {
                                for f in ALL_FIELDS { apply(&mut list, f, op_remove); }
                            }
                            _ => return Err(format!("unrecognized field start '{}'", lc)),
                        }
                        expect_start = false;
                    }
                }
            }
        }
        Ok(Fields(list))
    }
}

struct Args {
    help: bool,
    version: bool,
    color: String,
    key: Key,
    length: u64,
    fields: Fields,
    changes: bool,
    date: Option<String>,
    ip: Option<String>,
    method: Option<String>,
    path: Option<String>,
    referer: Option<String>,
    status: Option<String>,
    time: Option<String>,
    all: bool,
    no_name_check: bool,
    output: Output,
    silent_load: bool,
    files: Vec<String>,
}

fn build_cli() -> Command {
    Command::new("rhit")
        .disable_help_flag(true)
        .disable_version_flag(true)
        .arg(Arg::new("help").long("help").help("Print help information").action(ArgAction::SetTrue))
        .arg(Arg::new("version").long("version").help("Print the version").action(ArgAction::SetTrue))
        .arg(Arg::new("color").long("color").value_name("color").value_parser(["auto", "yes", "no"]).default_value("auto"))
        .arg(Arg::new("key").short('k').long("key").value_name("KEY").value_parser(clap::value_parser!(Key)).default_value("hits"))
        .arg(Arg::new("length").short('l').long("length").value_name("LENGTH").value_parser(clap::value_parser!(u64)).default_value("1"))
        .arg(Arg::new("fields").short('f').long("fields").value_name("FIELDS").value_parser(clap::value_parser!(Fields)).default_value("date,status,ref,path"))
        .arg(Arg::new("changes").short('c').long("changes").action(ArgAction::SetTrue))
        .arg(Arg::new("date").short('d').long("date").value_name("DATE"))
        .arg(Arg::new("ip").short('i').long("ip").value_name("IP"))
        .arg(Arg::new("method").short('m').long("method").value_name("METHOD"))
        .arg(Arg::new("path").short('p').long("path").value_name("PATH"))
        .arg(Arg::new("referer").short('r').long("referer").value_name("REFERER"))
        .arg(Arg::new("status").short('s').long("status").value_name("STATUS"))
        .arg(Arg::new("time").short('t').long("time").value_name("TIME"))
        .arg(Arg::new("all").short('a').long("all").action(ArgAction::SetTrue))
        .arg(Arg::new("no-name-check").long("no-name-check").action(ArgAction::SetTrue))
        .arg(Arg::new("output").short('o').long("output").value_name("OUTPUT").value_parser(clap::value_parser!(Output)).default_value("tables"))
        .arg(Arg::new("silent-load").long("silent-load").action(ArgAction::SetTrue))
        .arg(Arg::new("files").value_name("FILES").action(ArgAction::Append).num_args(0..))
}

fn parse_args() -> Args {
    let m = build_cli().get_matches();
    Args {
        help: m.get_flag("help"),
        version: m.get_flag("version"),
        color: m.get_one::<String>("color").cloned().unwrap_or_else(|| "auto".to_string()),
        key: *m.get_one::<Key>("key").unwrap_or(&Key::Hits),
        length: *m.get_one::<u64>("length").unwrap_or(&1),
        fields: m.get_one::<Fields>("fields").cloned().unwrap_or_else(|| Fields(DEFAULT_FIELDS.to_vec())),
        changes: m.get_flag("changes"),
        date: m.get_one::<String>("date").cloned(),
        ip: m.get_one::<String>("ip").cloned(),
        method: m.get_one::<String>("method").cloned(),
        path: m.get_one::<String>("path").cloned(),
        referer: m.get_one::<String>("referer").cloned(),
        status: m.get_one::<String>("status").cloned(),
        time: m.get_one::<String>("time").cloned(),
        all: m.get_flag("all"),
        no_name_check: m.get_flag("no-name-check"),
        output: *m.get_one::<Output>("output").unwrap_or(&Output::Tables),
        silent_load: m.get_flag("silent-load"),
        files: m.get_many::<String>("files").map(|v| v.cloned().collect()).unwrap_or_default(),
    }
}

// ---------- formatting helpers ----------
fn fmt_int(mut n: u64) -> String {
    if n < 1000 { return n.to_string(); }
    let mut parts: Vec<String> = Vec::new();
    while n >= 1000 {
        parts.push(format!("{:03}", n % 1000));
        n /= 1000;
    }
    parts.push(n.to_string());
    parts.reverse();
    parts.join(",")
}
fn fmt_bytes(n: u64) -> String {
    if n < 10_000 { return n.to_string(); }
    const UNITS: [&str; 5] = ["K", "M", "G", "T", "P"];
    let mut scaled = n as f64;
    let mut unit = "";
    let mut exhausted = true;
    for u in UNITS {
        scaled /= 1000.0;
        unit = u;
        if scaled < 999.5 { exhausted = false; break; }
    }
    if exhausted && scaled >= 999.5 { return "huge".to_string(); }
    if scaled < 10.0 {
        format!("{:.1}{}", scaled, unit)
    } else {
        format!("{:.0}{}", scaled, unit)
    }
}

// ---------- file discovery ----------
fn collect_dir(dir: &Path, out: &mut Vec<String>, no_name_check: bool) -> Result<(), Error> {
    let rd = std::fs::read_dir(dir)?;
    for entry in rd {
        let entry = entry?;
        let p = entry.path();
        if p.is_file() {
            if no_name_check || p.file_name().map(|n| n.to_string_lossy().contains("access.log")).unwrap_or(false) {
                out.push(p.to_string_lossy().to_string());
            }
        } else if p.is_dir() {
            collect_dir(&p, out, no_name_check)?;
        } else {
            return Err(Error::PathNotFound(p.to_string_lossy().to_string()));
        }
    }
    Ok(())
}
fn collect_candidates(inputs: &[String], no_name_check: bool) -> Result<Vec<String>, Error> {
    let mut out = Vec::new();
    for input in inputs {
        let p = Path::new(input);
        if p.is_file() {
            out.push(input.clone());
        } else if p.is_dir() {
            collect_dir(p, &mut out, no_name_check)?;
        } else {
            return Err(Error::PathNotFound(input.clone()));
        }
    }
    Ok(out)
}

fn open_reader(path: &str) -> Result<Box<dyn BufRead>, Error> {
    let file = std::fs::File::open(path)?;
    if path.ends_with(".gz") {
        Ok(Box::new(BufReader::new(GzDecoder::new(file))))
    } else {
        Ok(Box::new(BufReader::new(file)))
    }
}

fn first_datetime(path: &str) -> Result<Option<DateTime>, Error> {
    let mut reader = open_reader(path)?;
    let mut buf = String::new();
    loop {
        buf.clear();
        let n = reader.read_line(&mut buf)?;
        if n == 0 { return Ok(None); }
        if let Some(h) = parse_line(&buf) {
            return Ok(Some(h.datetime));
        }
    }
}

#[derive(Clone)]
struct DatedFile { path: String, first: DateTime }

// ---------- progress ----------
fn progress_bar(i: usize, n: usize) {
    let frac = if n == 0 { 0.0 } else { i as f64 / n as f64 };
    let mut eighths = (frac * 40.0 * 8.0).round() as i64;
    if eighths < 0 { eighths = 0; }
    if eighths > 320 { eighths = 320; }
    let full = eighths / 8;
    let rem = eighths % 8;
    let mut content = String::new();
    for _ in 0..full { content.push('█'); }
    let mut used = full as usize;
    if rem > 0 {
        content.push(match rem { 1 => '▏', 2 => '▎', 3 => '▍', 4 => '▌', 5 => '▋', 6 => '▊', _ => '▉' });
        used += 1;
    }
    for _ in used..40 { content.push(' '); }
    eprint!("\x1b7\x1b[2K{:>4} / {} \x1b[48;5;5m\x1b[38;5;11m{}\x1b[49m\x1b[39m\x1b8", i, n, content);
}

// ---------- filters application structures ----------
struct ParsedFilters {
    date: Option<DateTimeFilter>,
    ip: Option<StrFilter>,
    method: Option<MethodFilter>,
    path: Option<StrFilter>,
    referer: Option<StrFilter>,
    status: Option<StatusFilter>,
    time: Option<TimeFilter>,
}
impl ParsedFilters {
    fn accepts(&self, h: &Hit) -> bool {
        if let Some(f) = &self.date { if !f.accepts(h.datetime) { return false; } }
        if let Some(f) = &self.ip { if !f.accepts(&h.remote_addr) { return false; } }
        if let Some(f) = &self.method { if !f.accepts(h.method) { return false; } }
        if let Some(f) = &self.path { if !f.accepts(&h.path) { return false; } }
        if let Some(f) = &self.referer { if !f.accepts(&h.referer) { return false; } }
        if let Some(f) = &self.status { if !f.accepts(h.status) { return false; } }
        if let Some(f) = &self.time { if !f.accepts(h.datetime.time) { return false; } }
        true
    }
}

fn main() -> Result<(), Error> {
    let args = parse_args();
    if args.version {
        println!("rhit 2.0.4");
        return Ok(());
    }
    if args.help {
        print_help();
        return Ok(());
    }
    // determine inputs
    let mut inputs = args.files.clone();
    let mut used_default = false;
    if inputs.is_empty() {
        used_default = true;
        inputs = vec!["/var/log/nginx".to_string()];
    }
    let candidates = match collect_candidates(&inputs, args.no_name_check) {
        Ok(c) => c,
        Err(e) => {
            if used_default {
                eprintln!("No nginx log found at default location, do you have nginx set up?");
                eprintln!("If necessary, provide the path to the log file(s) as argument.");
                eprintln!("More information with 'rhit --help'.");
            }
            return Err(e);
        }
    };
    // dated files
    let mut dated: Vec<DatedFile> = Vec::new();
    for path in &candidates {
        if let Some(dt) = first_datetime(path)? {
            dated.push(DatedFile { path: path.clone(), first: dt });
        }
    }
    if dated.is_empty() {
        return Err(Error::NoLogFileFound);
    }
    dated.sort_by_key(|d| d.first);
    let reference = dated[0].first;

    // parse filters in application order
    let pf = ParsedFilters {
        date: match &args.date {
            Some(s) => Some(DateTimeFilter::parse(s, reference).map_err(Error::DateTime)?),
            None => None,
        },
        ip: match &args.ip {
            Some(s) => Some(StrFilter::from_str(s).map_err(Error::StrFilter)?),
            None => None,
        },
        method: args.method.as_ref().map(|s| MethodFilter::parse(s)),
        path: match &args.path {
            Some(s) => Some(StrFilter::from_str(s).map_err(Error::StrFilter)?),
            None => None,
        },
        referer: match &args.referer {
            Some(s) => Some(StrFilter::from_str(s).map_err(Error::StrFilter)?),
            None => None,
        },
        status: match &args.status {
            Some(s) => Some(StatusFilter::parse(s).map_err(Error::StatusFilter)?),
            None => None,
        },
        time: match &args.time {
            Some(s) => Some(TimeFilter::parse(s).map_err(Error::TimeFilter)?),
            None => None,
        },
    };

    let mode = output_mode(&args);
    let is_tables = args.output == Output::Tables;
    let n_files = dated.len();
    if !args.silent_load {
        progress_bar(0, n_files);
    }
    // output headers for export modes
    if !is_tables {
        match args.output {
            Output::Csv => println!("date,time,remote address,method,path,status,bytes sent,referer"),
            Output::Json => println!("["),
            _ => {}
        }
    }
    let mut hits: Vec<Hit> = Vec::new();
    let mut json_first = true;
    for (idx, df) in dated.iter().enumerate() {
        let mut reader = open_reader(&df.path)?;
        let mut buf = String::new();
        loop {
            buf.clear();
            let n = reader.read_line(&mut buf)?;
            if n == 0 { break; }
            if let Some(h) = parse_line(&buf) {
                if is_tables {
                    hits.push(h);
                } else if pf.accepts(&h) {
                    match args.output {
                        Output::Raw => {
                            print!("{}", buf);
                        }
                        Output::Csv => {
                            println!("{},{},{},{},\"{}\",{}, {},\"{}\"", h.datetime.date, h.datetime.time, h.remote_addr, h.method.name(), h.path, h.status, h.bytes_sent, h.referer);
                        }
                        Output::Json => {
                            if !json_first { println!(","); }
                            json_first = false;
                            print_json_hit(&h);
                        }
                        Output::Tables => unreachable!(),
                    }
                }
            }
        }
        if !args.silent_load {
            progress_bar(idx + 1, n_files);
        }
    }
    if !args.silent_load {
        let what = if inputs.len() == 1 {
            format!("{:?}", inputs[0])
        } else {
            format!("{:?}", inputs)
        };
        eprint!("\x1b7\x1b[2K\x1b8I've read {} {} in {}\n", n_files, if n_files == 1 { "file" } else { "files" }, what);
    }
    if !is_tables {
        if args.output == Output::Csv {
            // CSV format fix: our println above inserted a space before bytes (fixed below via replacement not possible)
        }
        if args.output == Output::Json {
            if !json_first { println!(); }
            println!("]");
        }
        return Ok(());
    }

    print_tables(&args, &mode, hits, &pf);
    Ok(())
}

fn print_json_hit(h: &Hit) {
    // matches the original's manual formatting (no escaping)
    print!("  {{\n    \"date\": \"{}\",\n    \"time\": \"{}\",\n    \"remote_addr\": \"{}\",\n    \"method\": \"{}\",\n    \"path\": \"{}\",\n    \"status\": \"{}\",\n    \"bytes_sent\": {},\n    \"referer\": \"{}\"\n  }}", h.datetime.date, h.datetime.time, h.remote_addr, h.method.name(), h.path, h.status, h.bytes_sent, h.referer);
}

fn output_mode(args: &Args) -> Mode {
    let stdout_tty = std::io::stdout().is_terminal();
    let enabled = match args.color.as_str() {
        "yes" => true,
        "no" => false,
        _ => stdout_tty,
    };
    if !enabled {
        Mode::Plain
    } else if std::env::var("NO_COLOR").map(|v| !v.is_empty()).unwrap_or(false) {
        Mode::NoColor
    } else {
        Mode::Color
    }
}

fn terminal_width() -> usize {
    let stdout = std::io::stdout();
    if !stdout.is_terminal() {
        return 50;
    }
    #[cfg(unix)]
    {
        #[repr(C)]
        struct Winsize { ws_row: u16, ws_col: u16, ws_xpixel: u16, ws_ypixel: u16 }
        let mut ws = Winsize { ws_row: 0, ws_col: 0, ws_xpixel: 0, ws_ypixel: 0 };
