const DEFAULT_FIELDS: [Field; 4] = [Field::Dates, Field::Status, Field::Referers, Field::Paths];

#[derive(Clone, Debug)]
struct Fields(Vec<Field>);
impl FromStr for Fields {
    type Err = String;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let mut list: Vec<Field> = Vec::new();
        let mut op_remove = false;
        let mut expect_start = true;
        let chars: Vec<char> = s.chars().collect();
        for (idx, c) in chars.iter().enumerate() {
            let c = *c;
            match c {
                '+' => {
                    if idx == 0 { list = DEFAULT_FIELDS.to_vec(); }
                    op_remove = false;
                    expect_start = true;
                }
                '-' => {
                    if idx == 0 { list = DEFAULT_FIELDS.to_vec(); }
                    op_remove = true;
                    expect_start = true;
                }
                ',' | ' ' => {
                    op_remove = false;
                    expect_start = true;
                }
                _ => {
                    if expect_start {
                        let lc = c.to_ascii_lowercase();
                        let apply = |list: &mut Vec<Field>, f: Field, remove: bool| {
                            if remove {
                                list.retain(|x| *x != f);
                            } else {
                                list.retain(|x| *x != f);
                                list.push(f);
                            }
                        };
                        match lc {
                            'd' => apply(&mut list, Field::Dates, op_remove),
                            't' => apply(&mut list, Field::Times, op_remove),
                            'm' => apply(&mut list, Field::Methods, op_remove),
                            's' => apply(&mut list, Field::Status, op_remove),
                            'i' => apply(&mut list, Field::Ip, op_remove),
                            'r' => apply(&mut list, Field::Referers, op_remove),
                            'p' => apply(&mut list, Field::Paths, op_remove),
