// ---------- tables printing ----------

fn bar_string(value: u64, max: u64, width: usize) -> String {
    if max == 0 || width == 0 { return String::new(); }
    let mut eighths = (value as f64 * (width as f64) * 8.0 / max as f64).round() as i64;
    let max_e = (width * 8) as i64;
    if eighths < 0 { eighths = 0; }
    if eighths > max_e { eighths = max_e; }
    let full = eighths / 8;
    let rem = eighths % 8;
    let mut s = String::new();
    for _ in 0..full { s.push('█'); }
    if rem > 0 {
        s.push(match rem { 1 => '▏', 2 => '▎', 3 => '▍', 4 => '▌', 5 => '▋', 6 => '▊', _ => '▉' });
    }
    s
}

fn sparkline(values: &[u64]) -> String {
    if values.is_empty() { return String::new(); }
    let max = *values.iter().max().unwrap_or(&0);
    let chars = [' ', '▁', '▂', '▃', '▄', '▅', '▆', '▇'];
    let mut s = String::new();
    for v in values {
        let lvl = if max == 0 { 0 } else { (*v as f64 * 7.0 / max as f64).round() as usize };
        s.push(chars[lvl.min(7)]);
    }
    s
}

fn key_of(h: &Hit, key: Key) -> u64 {
    match key { Key::Hits => 1, Key::Bytes => h.bytes_sent }
}

struct Agg {
    value: String,
    hits: u64,
    bytes: u64,
    hist: Vec<u64>,
    trend: f64,
}

fn trend_and_spark(agg_hist: &[u64], global_hist: &[u64]) -> (f64, String) {
    let n = agg_hist.len();
    let start = if n > 20 { n - 20 } else { 0 };
    let window = &agg_hist[start..];
    let gwindow = &global_hist[start..];
    let spark = sparkline(window);
    if window.len() <= 2 {
        return (0.0, spark);
    }
    let split = window.len() - 2;
    let row_recent: u64 = window[split..].iter().sum();
    let row_before: u64 = window[..split].iter().sum();
    let tot_recent: u64 = gwindow[split..].iter().sum();
    let tot_before: u64 = gwindow[..split].iter().sum();
    let share_recent = if tot_recent > 0 { row_recent as f64 / tot_recent as f64 } else { 0.0 };
    let share_before = if tot_before > 0 { row_before as f64 / tot_before as f64 } else { 0.0 };
    let denom = share_recent + share_before;
    let t = if denom == 0.0 { 0.0 } else { (share_recent - share_before) / denom };
    (t, spark)
}

fn trend_cell(t: f64) -> Cell {
    let count = if t > 0.9 { 3 } else if t > 0.5 { 2 } else if t > 0.2 { 1 } else if t < -0.9 { -3 } else if t < -0.5 { -2 } else if t < -0.2 { -1 } else { 0 };
    let mut segs: Vec<(String, Option<Style>)> = Vec::new();
    if count != 0 {
        let (ch, st) = if count > 0 { ('➚', Style::Green) } else { ('➘', Style::Red) };
        let n = count.abs();
        for i in 0..n {
            if i > 0 { segs.push((" ".to_string(), None)); }
            segs.push((ch.to_string(), Some(st)));
        }
    }
    Cell::from_segments(segs)
}

fn limit_for(field: Field, length: u64) -> usize {
    let v: u128 = match field {
        Field::Paths => if length == 0 { 10 } else { 50u128 * length as u128 },
        Field::Referers => match length { 0 => 5, 1 => 10, _ => 20u128 * length as u128 },
        Field::Ip => match length { 0 => 3, 1 => 5, _ => 10u128 * length as u128 },
        _ => usize::MAX as u128,
    };
    if v > usize::MAX as u128 { usize::MAX } else { v as usize }
}

fn label_of(field: Field, all: bool) -> String {
    match field {
        Field::Methods => "methods".to_string(),
        Field::Status => "HTTP status codes".to_string(),
        Field::Ip => "remote IP addresses".to_string(),
        Field::Referers => "referrers".to_string(),
        Field::Paths => {
            if all { "paths".to_string() } else { "paths (excluding resources like images, css, etc.)".to_string() }
        }
        _ => String::new(),
    }
}

fn print_paragraph_out(segments: Vec<(String, Option<Style>)>, width: usize, mode: &Mode) {
    for line in wrap_paragraph(&segments, width, *mode) {
        println!("{}", line);
    }
}

fn title_segments(field: Field, count_str: &str, count: u64, truncated: bool, limit: usize, extended: bool, all: bool) -> Vec<(String, Option<Style>)> {
    let label = label_of(field, all);
    // returns segments; plain text constructed from them (except path tokenization)
    let mut segs: Vec<(String, Option<Style>)> = Vec::new();
    let style = Some(Style::Title);
    if field == Field::Paths {
        let text = if truncated {
            format!("{} {}. {} most frequent:", count_str, label, limit)
        } else if extended {
            format!("{} {}", count_str, label)
        } else {
            format!("{} {}. ", count_str, label)
        };
        // tokenize by words and spaces, each as own segment; handle the short-mode trailing ". " differently
        if !extended && !truncated {
            // text ends with ". " where the '.' is separate in the original rendering
            // build from words of "<count> <label>" then "." and " "
            let base = format!("{} {}", count_str, label);
            let mut first = true;
            for part in base.split(' ') {
                if !first { segs.push((" ".to_string(), style)); }
                first = false;
                segs.push((part.to_string(), style));
            }
            segs.push((".".to_string(), style));
            segs.push((" ".to_string(), style));
        } else {
            let mut first = true;
            for part in text.split(' ') {
                if !first { segs.push((" ".to_string(), style)); }
                first = false;
                segs.push((part.to_string(), style));
            }
        }
        return segs;
    }
    if extended {
        if field == Field::Methods || field == Field::Status {
            segs.push((label, style));
        } else if truncated {
            segs.push((format!("{} {}. {} most frequent:", count_str, label, limit), style));
        } else {
            segs.push((format!("{} {}", count_str, label), style));
        }
    } else {
        // short
        segs.push((count_str.to_string(), style));
        segs.push((" ".to_string(), style));
        segs.push((label, style));
        segs.push((". ".to_string(), style));
        segs.push(("".to_string(), style));
    }
    segs
}

fn plain_of(segs: &[(String, Option<Style>)]) -> String {
    segs.iter().map(|(s, _)| s.as_str()).collect()
}

fn print_tables(args: &Args, mode: &Mode, hits: Vec<Hit>, pf: &ParsedFilters) {
    let width = terminal_width();
    let total_hits = hits.len() as u64;
    if total_hits == 0 { return; }
    let total_bytes: u64 = hits.iter().map(|h| h.bytes_sent).fold(0u64, |a, b| a.wrapping_add(b));
    let first_date = hits[0].datetime.date;
    let last_date = hits[hits.len() - 1].datetime.date;
    // original distinct dates (order of first appearance)
    let mut orig_dates: Vec<Date> = Vec::new();
    for h in &hits { if !orig_dates.contains(&h.datetime.date) { orig_dates.push(h.datetime.date); } }
    let mut date_index: HashMap<Date, usize> = HashMap::new();
    for (i, d) in orig_dates.iter().enumerate() { date_index.insert(*d, i); }

    // sequential filtering
    let mut current: Vec<&Hit> = hits.iter().collect();
    let mut filter_infos: Vec<(String, String, f64)> = Vec::new(); // label, pattern, removed percent
    let mut apply = |current: &mut Vec<&Hit>, label: &str, pattern: &Option<String>, accept: &dyn Fn(&Hit) -> bool, filter_infos: &mut Vec<(String, String, f64)>| {
        if let Some(pat) = pattern {
            let before = current.len() as u64;
            current.retain(|h| accept(h));
            let removed = before - current.len() as u64;
            let pct = removed as f64 * 100.0 / total_hits as f64;
            filter_infos.push((label.to_string(), pat.clone(), pct));
        }
    };
    // date first (needed for date domain)
    apply(&mut current, "date", &args.date, &|h: &Hit| pf.date.as_ref().map(|f| f.accepts(h.datetime)).unwrap_or(true), &mut filter_infos);
    let hits_after_date: Vec<&Hit> = current.clone();
    // date domain (distinct dates after date filter)
    let mut domain_dates: Vec<Date> = Vec::new();
    for h in &hits_after_date { if !domain_dates.contains(&h.datetime.date) { domain_dates.push(h.datetime.date); } }
    // effective dates: orig dates truncated after max index in hits_after_date
    let d_eff_len = if hits_after_date.is_empty() { 0 } else {
        let mut mx = 0usize;
        for h in &hits_after_date { if let Some(i) = date_index.get(&h.datetime.date) { mx = mx.max(*i); } }
        mx + 1
    };
    apply(&mut current, "remote address", &args.ip, &|h: &Hit| pf.ip.as_ref().map(|f| f.accepts(&h.remote_addr)).unwrap_or(true), &mut filter_infos);
    apply(&mut current, "method", &args.method, &|h: &Hit| pf.method.as_ref().map(|f| f.accepts(h.method)).unwrap_or(true), &mut filter_infos);
    apply(&mut current, "path", &args.path, &|h: &Hit| pf.path.as_ref().map(|f| f.accepts(&h.path)).unwrap_or(true), &mut filter_infos);
    apply(&mut current, "referer", &args.referer, &|h: &Hit| pf.referer.as_ref().map(|f| f.accepts(&h.referer)).unwrap_or(true), &mut filter_infos);
    apply(&mut current, "status", &args.status, &|h: &Hit| pf.status.as_ref().map(|f| f.accepts(h.status)).unwrap_or(true), &mut filter_infos);
    apply(&mut current, "time", &args.time, &|h: &Hit| pf.time.as_ref().map(|f| f.accepts(h.datetime.time)).unwrap_or(true), &mut filter_infos);

    let filtered = current;
    let filtered_hits = filtered.len() as u64;
    let filtered_bytes: u64 = filtered.iter().map(|h| h.bytes_sent).fold(0u64, |a, b| a.wrapping_add(b));

    // ---- header line ----
    {
        let (hits_txt, hits_style) = if args.key == Key::Hits { (fmt_int(total_hits), Some(Style::Pink)) } else { (fmt_int(total_hits), None) };
        let (bytes_txt, bytes_style) = if args.key == Key::Bytes { (fmt_bytes(total_bytes), Some(Style::Pink)) } else { (fmt_bytes(total_bytes), None) };
        let segs = vec![
            (hits_txt, hits_style),
            (" hits and ".to_string(), None),
            (bytes_txt, bytes_style),
            (" from ".to_string(), None),
            (first_date.to_string(), Some(Style::YellowBold)),
            (" to ".to_string(), None),
            (last_date.to_string(), Some(Style::YellowBold)),
        ];
        print_paragraph_out(segs, width, mode);
    }
    // ---- filter info ----
    for (label, pat, pct) in &filter_infos {
        let pct_txt = format!("{:.2}%", pct);
        let segs = vec![
            (format!("Filtering by {} on pattern ", label), None),
            (pat.clone(), Some(Style::Yellow)),
            (" removed ".to_string(), None),
            (pct_txt, Some(Style::YellowBold)),
            (" of total lines".to_string(), None),
        ];
        print_paragraph_out(segs, width, mode);
    }
    if !filter_infos.is_empty() {
        let (h_txt, h_style) = if args.key == Key::Hits { (fmt_int(filtered_hits), Some(Style::Pink)) } else { (fmt_int(filtered_hits), None) };
        let (b_txt, b_style) = if args.key == Key::Bytes { (fmt_bytes(filtered_bytes), Some(Style::Pink)) } else { (fmt_bytes(filtered_bytes), None) };
        let segs = vec![
            (" ".to_string(), None),
            ("==>".to_string(), Some(Style::YellowBold)),
            (" hits: ".to_string(), None),
            (h_txt, h_style),
            (", bytes sent: ".to_string(), None),
            (b_txt, b_style),
        ];
        // ==> line is not wrapped (observed long lines stay), print directly if plain rendering is one line
        let lines = wrap_paragraph(&segs, usize::MAX, *mode);
        for l in lines { println!("{}", l); }
    }
    if filtered_hits == 0 { return; }

    let extended = d_eff_len > 3;

    // global histogram (filtered hits) indexed by original date index
    let mut global_hist = vec![0u64; d_eff_len];
    for h in &filtered {
        if let Some(i) = date_index.get(&h.datetime.date) {
            if *i < d_eff_len { global_hist[*i] = global_hist[*i].wrapping_add(key_of(h, args.key)); }
        }
    }

    // helpers to build aggregates
    let build_agg = |value_fn: &dyn Fn(&Hit) -> Option<String>| -> Vec<Agg> {
        let mut aggs: Vec<Agg> = Vec::new();
        let mut index: HashMap<String, usize> = HashMap::new();
        for h in &filtered {
            if let Some(v) = value_fn(h) {
                let idx = *index.entry(v.clone()).or_insert_with(|| {
                    aggs.push(Agg { value: v, hits: 0, bytes: 0, hist: vec![0; d_eff_len], trend: 0.0 });
                    aggs.len() - 1
                });
                let a = &mut aggs[idx];
                a.hits += 1;
                a.bytes = a.bytes.wrapping_add(h.bytes_sent);
                if let Some(di) = date_index.get(&h.datetime.date) {
                    if *di < d_eff_len { a.hist[*di] = a.hist[*di].wrapping_add(key_of(h, args.key)); }
                }
            }
        }
        for a in aggs.iter_mut() {
            let (t, _) = trend_and_spark(&a.hist, &global_hist);
            a.trend = t;
        }
        aggs
    };

    for field in &args.fields.0 {
        match field {
            Field::Dates => {
                print_histogram_table(&filtered, true, args, mode, width, &domain_dates);
            }
            Field::Times => {
                print_histogram_table(&filtered, false, args, mode, width, &domain_dates);
            }
            Field::Methods => {
                let aggs = build_agg(&|h: &Hit| Some(h.method.name().to_string()));
                print_generic_table(args, mode, width, Field::Methods, aggs, &global_hist, extended, filtered_hits, d_eff_len);
            }
            Field::Status => {
                if args.length == 0 {
                    print_status_classes(&filtered, mode, width);
                } else {
                    let aggs = build_agg(&|h: &Hit| Some(h.status.to_string()));
                    print_generic_table(args, mode, width, Field::Status, aggs, &global_hist, extended, filtered_hits, d_eff_len);
                }
            }
            Field::Ip => {
                let aggs = build_agg(&|h: &Hit| Some(h.remote_addr.clone()));
                print_generic_table(args, mode, width, Field::Ip, aggs, &global_hist, extended, filtered_hits, d_eff_len);
            }
            Field::Referers => {
                let aggs = build_agg(&|h: &Hit| {
                    if h.referer == "-" || h.referer.trim().is_empty() { None } else { Some(h.referer.clone()) }
                });
                print_generic_table(args, mode, width, Field::Referers, aggs, &global_hist, extended, filtered_hits, d_eff_len);
            }
            Field::Paths => {
                let show_all = args.all;
                let aggs = build_agg(&|h: &Hit| {
                    if !show_all && is_resource(&h.path) { None } else { Some(h.path.clone()) }
                });
                print_generic_table(args, mode, width, Field::Paths, aggs, &global_hist, extended, filtered_hits, d_eff_len);
            }
        }
    }
}

fn is_resource(path: &str) -> bool {
    const EXTS: [&str; 10] = [".png", ".jpg", ".jpeg", ".gif", ".css", ".js", ".ico", ".svg", ".webp", ".woff2"];
    EXTS.iter().any(|e| path.ends_with(e))
}

fn print_histogram_table(filtered: &[&Hit], is_date: bool, args: &Args, mode: &Mode, width: usize, domain_dates: &[Date]) {
    // build rows
    let mut rows_data: Vec<(String, u64, u64, u64)> = Vec::new(); // label, hits, bytes, key
    if is_date {
        for d in domain_dates {
            let mut hits = 0u64;
            let mut bytes = 0u64;
            let mut key = 0u64;
            for h in filtered.iter().filter(|h| h.datetime.date == *d) {
                hits += 1;
                bytes = bytes.wrapping_add(h.bytes_sent);
                key = key.wrapping_add(key_of(h, args.key));
            }
            rows_data.push((d.to_string(), hits, bytes, key));
        }
    } else {
        for hour in 0u8..24 {
            let mut hits = 0u64;
            let mut bytes = 0u64;
            let mut key = 0u64;
            for h in filtered.iter().filter(|h| h.datetime.time.hour == hour) {
                hits += 1;
                bytes = bytes.wrapping_add(h.bytes_sent);
                key = key.wrapping_add(key_of(h, args.key));
            }
            rows_data.push((hour.to_string(), hits, bytes, key));
        }
    }
    let max_key = rows_data.iter().map(|r| r.3).max().unwrap_or(0);
    let max_str = if args.key == Key::Hits { max_key.to_string() } else { fmt_bytes(max_key) };
    let bar_header = format!("0{:>19}", max_str);
    let header_cells = vec![
        Cell::styled(if is_date { "date" } else { "hour" }, Style::YellowBold),
        Cell::styled("hits", Style::YellowBold),
        Cell::styled("bytes", Style::YellowBold),
        Cell::styled(bar_header.clone(), Style::YellowBold),
    ];
    let mut rows: Vec<Vec<Cell>> = Vec::new();
    for (label, hits, bytes, keyv) in &rows_data {
        let bar = bar_string(*keyv, max_key, 20);
        rows.push(vec![
            Cell::plain(label.clone()),
            {
                let c = Cell::styled(fmt_int(*hits), Style::Pink);
                if args.key == Key::Hits { c } else { Cell::plain(fmt_int(*hits)) }
            },
            {
                if args.key == Key::Bytes { Cell::styled(fmt_bytes(*bytes), Style::Pink) } else { Cell::plain(fmt_bytes(*bytes)) }
            },
            Cell::styled(bar, Style::Pink),
        ]);
    }
    // header style: headers are yellow bold tokens; plain rendering ignores style
    let table = Table {
        headers: header_cells,
        header_aligns: vec![Align::Center, Align::Center, Align::Center, Align::Center],
        aligns: if is_date { vec![Align::Left, Align::Right, Align::Right, Align::Left] } else { vec![Align::Left, Align::Center, Align::Right, Align::Left] },
        rows,
    };
    for line in table.render(width, *mode) { println!("{}", line); }
}

fn print_status_classes(filtered: &[&Hit], mode: &Mode, width: usize) {
    // title
    print_paragraph_out(vec![("HTTP status codes:".to_string(), Some(Style::Title))], width, mode);
    let total = filtered.len() as f64;
    let mut counts = [0u64; 4];
    for h in filtered {
        match h.status / 100 {
            2 => counts[0] += 1,
            3 => counts[1] += 1,
            4 => counts[2] += 1,
            _ => counts[3] += 1,
        }
    }
    let headers = ["2xx", "3xx", "4xx", "5xx"];
    let table = Table {
        headers: headers.iter().map(|s| Cell::styled(*s, Style::YellowBold)).collect(),
        header_aligns: vec![Align::Center, Align::Center, Align::Center, Align::Center],
        aligns: vec![Align::Center, Align::Center, Align::Center, Align::Center],
        rows: vec![counts.iter().map(|c| {
            let pct = if total > 0.0 { *c as f64 * 100.0 / total } else { 0.0 };
            Cell::plain(format!("{:.1}%", pct))
        }).collect()],
    };
    for line in table.render(width, *mode) { println!("{}", line); }
}

fn sorted_aggs(aggs: &mut Vec<Agg>, key: Key) {
    // stable sort descending by key value
    aggs.sort_by(|a, b| {
        let ka = if key == Key::Hits { a.hits } else { a.bytes };
        let kb = if key == Key::Hits { b.hits } else { b.bytes };
        kb.cmp(&ka)
    });
}

fn generic_columns_and_rows(
    args: &Args, field: Field, rows_to_show: &[Agg], filtered_hits: u64, extended: bool, global_hist: &[u64], d_eff_len: usize, rank_start: usize,
) -> Table {
    // returns a Table for the given rows (already limited)
    let value_header = match field {
        Field::Methods => "method",
        Field::Status => "status",
        Field::Ip => "IP address",
        Field::Referers => "referrer",
        Field::Paths => "path",
        _ => "",
    };
    let mut headers: Vec<Cell> = Vec::new();
    let mut header_aligns: Vec<Align> = Vec::new();
    let mut aligns: Vec<Align> = Vec::new();
    let is_status_method = field == Field::Status || field == Field::Methods;
    if extended {
        if !is_status_method {
            headers.push(Cell::styled("#", Style::YellowBold)); header_aligns.push(Align::Center); aligns.push(Align::Right);
        }
        headers.push(Cell::styled(value_header, Style::YellowBold)); header_aligns.push(if is_status_method { Align::Center } else { Align::Left }); aligns.push(if is_status_method { Align::Center } else { Align::Left });
        headers.push(Cell::styled("hits", Style::YellowBold)); header_aligns.push(Align::Center); aligns.push(Align::Right);
        if is_status_method {
            headers.push(Cell::styled("%", Style::YellowBold)); header_aligns.push(Align::Center); aligns.push(Align::Right);
        }
        headers.push(Cell::styled("bytes", Style::YellowBold)); header_aligns.push(Align::Center); aligns.push(Align::Right);
        headers.push(Cell::styled("days", Style::YellowBold)); header_aligns.push(Align::Center); aligns.push(Align::Right);
        headers.push(Cell::styled("trend", Style::YellowBold)); header_aligns.push(Align::Center); aligns.push(Align::Center);
    } else {
        headers.push(Cell::styled("#", Style::YellowBold)); header_aligns.push(Align::Center); aligns.push(Align::Right);
        headers.push(Cell::styled(value_header, Style::YellowBold)); header_aligns.push(Align::Left); aligns.push(Align::Left);
        headers.push(Cell::styled("hits", Style::YellowBold)); header_aligns.push(Align::Center); aligns.push(Align::Right);
        headers.push(Cell::styled("%", Style::YellowBold)); header_aligns.push(Align::Center); aligns.push(Align::Right);
        headers.push(Cell::styled("bytes", Style::YellowBold)); header_aligns.push(Align::Center); aligns.push(Align::Right);
    }
    let mut rows: Vec<Vec<Cell>> = Vec::new();
    for (i, a) in rows_to_show.iter().enumerate() {
        let mut row: Vec<Cell> = Vec::new();
        if !extended || !is_status_method {
            row.push(Cell::plain(format!("{}", rank_start + i)));
        }
        row.push(Cell::plain(a.value.clone()));
        if args.key == Key::Hits {
            row.push(Cell::styled(fmt_int(a.hits), Style::Pink));
        } else {
            row.push(Cell::plain(fmt_int(a.hits)));
        }
        if !extended || is_status_method {
            let pct = if filtered_hits > 0 { a.hits as f64 * 100.0 / filtered_hits as f64 } else { 0.0 };
            row.push(Cell::plain(format!("{:.1}%", pct)));
        }
        if args.key == Key::Bytes {
            row.push(Cell::styled(fmt_bytes(a.bytes), Style::Pink));
        } else {
            row.push(Cell::plain(fmt_bytes(a.bytes)));
        }
        if extended {
            let (_, spark) = trend_and_spark(&a.hist, global_hist);
            let _ = d_eff_len;
            row.push(Cell::styled(spark, Style::Pink));
            row.push(trend_cell(a.trend));
        }
        rows.push(row);
    }
    Table { headers, header_aligns, aligns, rows }
}

fn print_generic_table(args: &Args, mode: &Mode, width: usize, field: Field, mut aggs: Vec<Agg>, global_hist: &[u64], extended: bool, filtered_hits: u64, d_eff_len: usize) {
    let count = aggs.len();
    let count_str = fmt_int(count as u64);
    let limit = limit_for(field, args.length);
    let truncated = count > limit;
    // ---- normal table ----
    if extended && count == 0 {
        let label = label_of(field, args.all);
        println!("{} {} : none", count_str, label);
    } else {
        // status with length 0 handled elsewhere; here generic titles
        if field == Field::Status && args.length == 0 {
            // not reached
        } else {
            let segs = title_segments(field, &count_str, count as u64, truncated, limit, extended, args.all);
            print_paragraph_out(segs, width, mode);
        }
        sorted_aggs(&mut aggs, args.key);
        let show: Vec<Agg> = aggs.iter().take(limit.min(count)).cloned_agg();
        let table = generic_columns_and_rows(args, field, &show, filtered_hits, extended, global_hist, d_eff_len, 1);
        for line in table.render(width, *mode) { println!("{}", line); }
    }
    // ---- changes ----
    if !args.changes { return; }
    if !extended { return; }
    if !(matches!(field, Field::Paths | Field::Referers | Field::Ip)) { return; }
    if filtered_hits <= limit as u64 { return; }
    let change_limit: usize = if args.length == 0 { 5 } else { (10u128 * (args.length as u128)).min(usize::MAX as u128) as usize };
    // qualified rows: hits >= 10, sorted by trend
    let mut qualified: Vec<Agg> = aggs.iter().filter(|a| a.hits >= 10).cloned_agg();
    // More popular: trend descending
    let mut more = qualified.clone();
    more.sort_by(|a, b| b.trend.partial_cmp(&a.trend).unwrap_or(std::cmp::Ordering::Equal).then_with(|| {
        let ka = if args.key == Key::Hits { a.hits } else { a.bytes };
        let kb = if args.key == Key::Hits { b.hits } else { b.bytes };
        ka.cmp(&kb)
    }));
    let mut less = qualified.clone();
    less.sort_by(|a, b| a.trend.partial_cmp(&b.trend).unwrap_or(std::cmp::Ordering::Equal).then_with(|| {
        let ka = if args.key == Key::Hits { a.hits } else { a.bytes };
        let kb = if args.key == Key::Hits { b.hits } else { b.bytes };
        kb.cmp(&ka)
    }));
    let label = label_of(field, args.all);
    for (more_flag, list) in [(true, &more), (false, &less)] {
        let title = if more_flag { format!("More popular {}", label) } else { format!("Less popular {}", label) };
        let show: Vec<Agg> = list.iter().take(change_limit).cloned_agg();
        if show.is_empty() {
            println!("{} : none", title);
        } else {
            // title as paragraph: use path-style tokenization for paths, single segment otherwise
            let segs = changes_title_segments(field, &title);
            print_paragraph_out(segs, width, mode);
            let table = generic_columns_and_rows(args, field, &show, filtered_hits, extended, global_hist, d_eff_len, 1);
            for line in table.render(width, *mode) { println!("{}", line); }
        }
    }
    let _ = &mut qualified;
}

fn changes_title_segments(field: Field, title: &str) -> Vec<(String, Option<Style>)> {
    let style = Some(Style::Title);
    if field == Field::Paths {
        let mut segs = Vec::new();
        let mut first = true;
        for part in title.split(' ') {
            if !first { segs.push((" ".to_string(), style)); }
            first = false;
            segs.push((part.to_string(), style));
        }
        segs
    } else {
        vec![(title.to_string(), style)]
    }
}

trait ClonedAgg { fn cloned_agg(&self) -> Vec<Agg>; }
impl ClonedAgg for Vec<Agg> {
    fn cloned_agg(&self) -> Vec<Agg> {
        self.iter().map(|a| Agg { value: a.value.clone(), hits: a.hits, bytes: a.bytes, hist: a.hist.clone(), trend: a.trend }).collect()
    }
}
impl ClonedAgg for &[Agg] {
    fn cloned_agg(&self) -> Vec<Agg> {
        self.iter().map(|a| Agg { value: a.value.clone(), hits: a.hits, bytes: a.bytes, hist: a.hist.clone(), trend: a.trend }).collect()
    }
}
