    fn code(s: &str) -> (String, Option<Style>) { (s.to_string(), Some(Style::CodeBg)) }
    let opts: Vec<Opt> = vec![
        Opt { short: "", long: "--help", value: "", desc: vec![plain("Print help information")] },
        Opt { short: "", long: "--version", value: "", desc: vec![plain("Print the version")] },
        Opt { short: "", long: "--color", value: "color", desc: vec![plain("Whether to have styles and colors\n Possible values: ["), code("auto"), plain(", "), code("yes"), plain(", "), code("no"), plain("]\n Default: "), code("auto")] },
        Opt { short: "-k", long: "--key", value: "KEY", desc: vec![plain("Key used in sorting and histogram, either "), code("hits"), plain(" or "), code("bytes"), plain("\n Default: "), code("hits")] },
        Opt { short: "-l", long: "--length", value: "LENGTH", desc: vec![plain("Detail level, from "), code("0"), plain(" to "), code("6"), plain(", impacts the lengths of tables\n Default: "), code("1")] },
        Opt { short: "-f", long: "--fields", value: "FIELDS", desc: vec![plain("Comma separated list of hit fields to display. Use "), code("-f a"), plain(" to get all fields. Use "), code("-f +i"), plain(" to add ip. Available fields: "), code("date,time,method,status,ip,ref,path"), plain("\n Default: "), code("date,status,ref,path")] },
        Opt { short: "-c", long: "--changes", value: "", desc: vec![plain("Add tables with more popular and less popular entries (ip, referers and paths)")] },
        Opt { short: "-d", long: "--date", value: "DATE", desc: vec![plain("Filter the dates on a precise day or in an inclusive range (eg: "), code("-d 12/24"), plain(" or "), code("-d '2021/12/24-2022/01/21'"), plain(")")] },
        Opt { short: "-i", long: "--ip", value: "IP", desc: vec![plain("Ip address to filter by. May be negated with a !")] },
        Opt { short: "-m", long: "--method", value: "METHOD", desc: vec![plain("HTTP method to filter by. Make it negative with a !. (eg: "), code("-m PUT"), plain(" or "), code("-m !DELETE"), plain(" or "), code("-m none"), plain(" or "), code("-m other"), plain(")")] },
        Opt { short: "-p", long: "--path", value: "PATH", desc: vec![plain("Pattern for path filtering (eg: "), code("-p broot"), plain(" or "), code("-p '^/\\d+'"), plain(" or "), code("-p 'miaou | blog'"), plain(")")] },
        Opt { short: "-r", long: "--referer", value: "REFERER", desc: vec![plain("Referrer filter")] },
        Opt { short: "-s", long: "--status", value: "STATUS", desc: vec![plain("Comma separated list of statuses or status ranges to filter by (eg: "), code("-s 514"), plain(" or "), code("-s 4xx,5xx"), plain(", or "), code("-s 310-340,400-450"), plain(" or "), code("-s 5xx,!502"), plain(")")] },
        Opt { short: "-t", long: "--time", value: "TIME", desc: vec![plain("Filter the time of the day, in the logs' timezone (eg: "), code("-t '>19:30'"), plain(" to get evening hits)")] },
        Opt { short: "-a", long: "--all", value: "", desc: vec![plain("Show all paths, including resources")] },
        Opt { short: "", long: "--no-name-check", value: "", desc: vec![plain("Try to open all files, whatever their names")] },
        Opt { short: "-o", long: "--output", value: "OUTPUT", desc: vec![plain("Output: by default pretty summary tables but you can also output log lines as "), code("csv"), plain(", "), code("json"), plain(", or "), code("raw"), plain(" (as they appear in the log files)\n Default: "), code("tables")] },
        Opt { short: "", long: "--silent-load", value: "", desc: vec![plain("Don't print anything during load: no progress bar or file list")] },
    ];
    let mut rows: Vec<Vec<Cell>> = Vec::new();
    for o in &opts {
        rows.push(vec![
            Cell::plain(o.short.to_string()),
            Cell::plain(o.long.to_string()),
            Cell::plain(o.value.to_string()),
            Cell::from_segments(o.desc.clone()),
        ]);
    }
    let table = Table {
        headers: vec![Cell::styled("short", Style::YellowBold), Cell::styled("long", Style::YellowBold), Cell::styled("value", Style::YellowBold), Cell::styled("description", Style::YellowBold)],
        header_aligns: vec![Align::Center, Align::Center, Align::Center, Align::Left],
        aligns: vec![Align::Left, Align::Left, Align::Center, Align::Left],
        rows,
    };
    for line in table.render(width, mode) { println!("{}", line); }
    println!();
}
