import pathlib
p=pathlib.Path("src/render.rs"); t=p.read_text()
start=t.find("fn fit_widths")
end=t.find("\nimpl Table {")
old=t[start:end]
new='''fn fit_widths(natural: &[usize], avail: usize) -> Vec<usize> {
    let n = natural.len();
    if n == 0 { return Vec::new(); }
    let borders = n + 1;
    let natural_total: usize = natural.iter().sum::<usize>() + borders;
    if natural_total <= avail { return natural.to_vec(); }
    let target = avail.saturating_sub(borders);
    let sum_nat: usize = natural.iter().sum();
    if sum_nat == 0 || target == 0 { return natural.to_vec(); }
    let scale = target as f64 / sum_nat as f64;
    let mut widths: Vec<usize> = natural.iter().map(|w| (*w as f64 * scale).floor() as usize).collect();
    let fracs: Vec<f64> = natural.iter().map(|w| { let x = *w as f64 * scale; x - x.floor() }).collect();
    let mut rem = target as i64 - widths.iter().sum::<usize>() as i64;
    let mut order: Vec<usize> = (0..n).collect();
    order.sort_by(|a, b| fracs[*b].partial_cmp(&fracs[*a]).unwrap_or(std::cmp::Ordering::Equal).then_with(|| natural[*b].cmp(&natural[*a])).then_with(|| a.cmp(b)));
    let mut idx = 0usize;
    while rem > 0 {
        if order.is_empty() { break; }
        let i = order[idx % order.len()];
        if widths[i] < natural[i] {
            widths[i] += 1;
            rem -= 1;
        }
        idx += 1;
        if idx > 10000 { break; }
    }
    // minimum widths: small columns keep their natural width, others at least 4
    let mins: Vec<usize> = natural.iter().map(|w| if *w <= 5 { *w } else { 4 }).collect();
    for i in 0..n {
        if widths[i] < mins[i] { widths[i] = mins[i]; }
    }
    while widths.iter().sum::<usize>() > target {
        // reduce widest column above its minimum
        let mut best: Option<usize> = None;
        for i in 0..n {
            if widths[i] > mins[i] {
                match best { None => best = Some(i), Some(b) => { if widths[i] > widths[b] { best = Some(i); } } }
            }
        }
        match best {
            Some(i) => widths[i] -= 1,
            None => {
                // fallback: reduce widest above 1
                let mut best2: Option<usize> = None;
                for i in 0..n {
                    if widths[i] > 1 {
                        match best2 { None => best2 = Some(i), Some(b) => { if widths[i] > widths[b] { best2 = Some(i); } } }
                    }
                }
                match best2 { Some(i) => widths[i] -= 1, None => break }
            }
        }
    }
    widths
}

'''
t=t[:start]+new+t[end:]
p.write_text(t)
print("replaced")
