        // reduce widest column above its minimum
        let mut best: Option<usize> = None;
        for i in 0..n {
            if widths[i] > mins[i] {
                match best { None => best = Some(i), Some(b) => { if widths[i] > widths[b] { best = Some(i); } } }
            }
        }
        match best {
            Some(i) => widths[i] -= 1,
            None => {
                // fallback: reduce widest above 1
                let mut best2: Option<usize> = None;
                for i in 0..n {
                    if widths[i] > 1 {
                        match best2 { None => best2 = Some(i), Some(b) => { if widths[i] > widths[b] { best2 = Some(i); } } }
                    }
                }
                match best2 { Some(i) => widths[i] -= 1, None => break }
            }
        }
    }
