import pty, os, subprocess, re, struct, fcntl, termios
def run_pty(args, cols=120):
    master, slave = pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH", 50, cols, 0,0))
    p=subprocess.Popen(args, stdout=slave, stderr=subprocess.PIPE, stdin=subprocess.DEVNULL)
    os.close(slave); out=b""
    while True:
        try:
            d=os.read(master,65536)
            if not d: break
            out+=d
        except OSError: break
    p.wait(); os.close(master)
    return re.sub(r'\x1b\[[0-9;]*m|\r','',out.decode())
