                Some(pd) if pd == h.datetime.date => { h.bucket = b; }
                _ => {
                    if prev.is_some() { b += 1; }
                    h.bucket = b;
                    prev = Some(h.datetime.date);
                }
            }
            if prev.is_none() { prev = Some(h.datetime.date); }
        }
    }
