        let mut seen: Vec<Date> = Vec::new();
        for h in &hits_after_date {
            if h.chunk == *chunk && !seen.contains(&h.datetime.date) { seen.push(h.datetime.date); }
        }
        for d in seen { domain_entries.push((*chunk, d)); }
    }'''
