        for h in &hits_after_date {
            if !seen_buckets.contains(&h.bucket) { seen_buckets.push(h.bucket); }
        }
        seen_buckets.sort_unstable();
        for b in seen_buckets { domain_entries.push((b, bucket_dates[b])); }
    }'''
