# global hist and agg hist use bucket directly
t=t.replace("""    for h in &filtered {
        if let Some(i) = date_index.get(&(h.chunk, h.datetime.date)) {
            if *i < d_eff_len { global_hist[*i] = global_hist[*i].wrapping_add(key_of(h, args.key)); }
        }
    }""", """    for h in &filtered {
