                    if *di < d_eff_len { a.hist[*di] = a.hist[*di].wrapping_add(key_of(h, args.key)); }
                }""", """                if h.bucket < d_eff_len { a.hist[h.bucket] = a.hist[h.bucket].wrapping_add(key_of(h, args.key)); }""")
