t=t.replace("for h in filtered.iter().filter(|h| h.chunk == *chunk && h.datetime.date == *d) {",
              "for h in filtered.iter().filter(|h| h.bucket == *chunk && h.datetime.date == *d) {")
# unused orig_entries warning ignore; keep
p.write_text(t)
print("ok")
